import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/auth";
import { toast } from "sonner";
import { Plus, PencilSimple, Trash, ShareNetwork } from "@phosphor-icons/react";

const EMPTY = {
  title: "", brand: "BMW", model: "", chassis: "", position: "", year_from: 2018, year_to: 2024,
  part_type: "headlight", condition: "Refurbished", price: 0, stock: 1,
  description: "", warranty: "12 months", images: [""], sku: "",
};

export default function Admin() {
  const { user, loading } = useAuth();
  const [tab, setTab] = useState("products");
  const [products, setProducts] = useState([]);
  const [orders, setOrders] = useState([]);
  const [editing, setEditing] = useState(null);

  const reload = async () => {
    const [p, o] = await Promise.all([api.get("/products?limit=200"), api.get("/admin/orders").catch(() => ({ data: [] }))]);
    setProducts(p.data);
    setOrders(o.data || []);
  };
  useEffect(() => { if (user?.role === "admin") reload(); }, [user]);

  if (loading) return <div className="mx-auto max-w-7xl px-4 pb-16 pt-40 text-ink-3 md:px-8">Loading</div>;
  if (!user) return <div className="mx-auto max-w-7xl px-4 pb-16 pt-40 text-ink-3 md:px-8">Sign in required.</div>;
  if (user.role !== "admin") return <div className="mx-auto max-w-7xl px-4 pb-16 pt-40 text-ink-3 md:px-8">Admin only. Your role: {user.role}. Set ADMIN_EMAILS in backend .env to include {user.email}.</div>;

  const save = async (p) => {
    const payload = { ...p, price: parseFloat(p.price), stock: parseInt(p.stock || 0), year_from: parseInt(p.year_from), year_to: parseInt(p.year_to), images: typeof p.images === "string" ? p.images.split(",").map(s => s.trim()).filter(Boolean) : p.images };
    if (p.product_id) {
      await api.put(`/admin/products/${p.product_id}`, payload);
    } else {
      payload.slug = (payload.slug || payload.title.toLowerCase().replace(/\s+/g, "-").replace(/[()/]/g, ""));
      await api.post("/admin/products", payload);
    }
    setEditing(null); reload(); toast.success("Saved");
  };
  const del = async (id) => { if (!confirm("Delete this product?")) return; await api.delete(`/admin/products/${id}`); reload(); };
  const ebay = async (id) => { const { data } = await api.post(`/admin/integrations/ebay/list/${id}`); toast.success(`eBay: ${data.listing_id}`, { description: data.message || data.mode }); reload(); };
  const fb = async (id) => { const { data } = await api.post(`/admin/integrations/facebook/sync/${id}`); toast.success(`FB: ${data.feed_id}`, { description: data.message || data.mode }); reload(); };

  return (
    <div className="max-w-7xl mx-auto px-4 md:px-8 pt-32 pb-16 md:pt-40" data-testid="admin-page">
      <h1 className="font-display text-4xl font-extrabold mb-6">Admin</h1>
      <div className="flex gap-2 border-b border-ink/10 mb-8">
        {["products", "orders", "integrations"].map((t) => (
          <button key={t} onClick={() => setTab(t)} className={`px-5 py-3 text-sm uppercase tracking-widest ${tab === t ? "border-b-2 border-signal text-ink" : "text-ink-3"}`} data-testid={`tab-${t}`}>{t}</button>
        ))}
      </div>

      {tab === "products" && (
        <>
          <button onClick={() => setEditing({ ...EMPTY })} className="mb-6 rounded-full bg-ink text-white px-5 py-2.5 text-sm uppercase tracking-widest inline-flex items-center gap-2" data-testid="new-product-btn">
            <Plus size={14} /> New product
          </button>
          <div className="border border-ink/10">
            <table className="w-full text-sm">
              <thead className="bg-white text-xs uppercase tracking-widest text-ink-3">
                <tr><th className="text-left p-3">Title</th><th className="text-left p-3">Brand</th><th className="text-left p-3">Type</th><th className="text-left p-3">Price</th><th className="text-left p-3">Stock</th><th className="text-left p-3">Sync</th><th></th></tr>
              </thead>
              <tbody>
                {products.map((p) => (
                  <tr key={p.product_id} className="border-t border-ink/5" data-testid={`admin-row-${p.product_id}`}>
                    <td className="p-3">{p.title}</td>
                    <td className="p-3 text-ink-2">{p.brand}</td>
                    <td className="p-3 text-ink-2">{p.part_type}</td>
                    <td className="p-3">${p.price}</td>
                    <td className="p-3">{p.stock}</td>
                    <td className="p-3 text-xs text-ink-3">
                      <div className="flex gap-2">
                        <button onClick={() => ebay(p.product_id)} className="border border-ink/10 px-2 py-1 hover:border-signal" data-testid={`ebay-sync-${p.product_id}`} title="List on eBay"><ShareNetwork size={12} /> eBay {p.ebay_listing_id ? "✓" : ""}</button>
                        <button onClick={() => fb(p.product_id)} className="border border-ink/10 px-2 py-1 hover:border-signal" data-testid={`fb-sync-${p.product_id}`} title="Sync to Facebook"><ShareNetwork size={12} /> FB {p.meta_feed_id ? "✓" : ""}</button>
                      </div>
                    </td>
                    <td className="p-3 text-right">
                      <button onClick={() => setEditing(p)} className="text-ink-2 hover:text-ink mr-3" data-testid={`edit-${p.product_id}`}><PencilSimple size={14} /></button>
                      <button onClick={() => del(p.product_id)} className="text-ink-2 hover:text-red-600" data-testid={`delete-${p.product_id}`}><Trash size={14} /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === "orders" && (
        <div className="border border-ink/10">
          <table className="w-full text-sm">
            <thead className="bg-white text-xs uppercase tracking-widest text-ink-3">
              <tr><th className="text-left p-3">Order</th><th className="text-left p-3">Email</th><th className="text-left p-3">Total</th><th className="text-left p-3">Provider</th><th className="text-left p-3">Status</th><th className="text-left p-3">Date</th></tr>
            </thead>
            <tbody>
              {orders.map((o) => (
                <tr key={o.order_id} className="border-t border-ink/5">
                  <td className="p-3 font-mono text-xs">{o.order_id}</td>
                  <td className="p-3">{o.user_email || "guest"}</td>
                  <td className="p-3">${o.total.toFixed(2)}</td>
                  <td className="p-3">{o.provider}</td>
                  <td className="p-3"><span className={o.status === "paid" ? "text-signal" : "text-ink-2"}>{o.status}</span></td>
                  <td className="p-3 text-xs text-ink-3">{new Date(o.created_at).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {tab === "integrations" && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-6">
            <h3 className="font-display text-2xl font-bold">eBay auto-listing</h3>
            <p className="text-sm text-ink-2 mt-2">Add EBAY_APP_ID, EBAY_DEV_ID, EBAY_CERT_ID and EBAY_USER_TOKEN to backend .env to enable live listing. Currently in stub mode for development.</p>
            <p className="text-xs text-ink-3 mt-3">Sandbox setup → developer.ebay.com</p>
          </div>
          <div className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-6">
            <h3 className="font-display text-2xl font-bold">Facebook Commerce</h3>
            <p className="text-sm text-ink-2 mt-2">Add META_ACCESS_TOKEN and META_CATALOG_ID to backend .env. Use the public feed at <code className="text-signal">/api/feed/facebook.csv</code> in Commerce Manager.</p>
          </div>
        </div>
      )}

      {editing && <Editor item={editing} onClose={() => setEditing(null)} onSave={save} />}
    </div>
  );
}

function Editor({ item, onClose, onSave }) {
  const [p, setP] = useState({ ...item, images: (item.images || []).join(", ") });
  const Field = ({ k, label, type = "text", textarea }) => (
    <label className="block">
      <span className="text-xs uppercase tracking-widest text-ink-3">{label}</span>
      {textarea ? (
        <textarea value={p[k] ?? ""} onChange={(e) => setP({ ...p, [k]: e.target.value })} rows={4}
          className="mt-1 w-full bg-white border border-ink/10 px-3 py-2 text-sm outline-none focus:border-signal" data-testid={`field-${k}`} />
      ) : (
        <input type={type} value={p[k] ?? ""} onChange={(e) => setP({ ...p, [k]: e.target.value })}
          className="mt-1 w-full bg-white border border-ink/10 px-3 py-2 text-sm outline-none focus:border-signal" data-testid={`field-${k}`} />
      )}
    </label>
  );
  return (
    <div className="fixed inset-0 bg-ink/40 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={onClose} data-testid="product-editor">
      <div onClick={(e) => e.stopPropagation()} className="bg-white border border-ink/10 w-full max-w-2xl p-6 max-h-[90vh] overflow-y-auto">
        <h3 className="font-display text-2xl font-bold mb-4">{p.product_id ? "Edit" : "New"} product</h3>
        <div className="grid grid-cols-2 gap-4">
          <div className="col-span-2"><Field k="title" label="Title" /></div>
          <Field k="brand" label="Brand (BMW/Mercedes/Audi)" />
          <Field k="model" label="Model (e.g. 3 Series)" />
          <Field k="chassis" label="Chassis code (e.g. G20)" />
          <Field k="year_from" label="Year from" type="number" />
          <Field k="year_to" label="Year to" type="number" />
          <Field k="part_type" label="Part type (bumper/headlight/taillight)" />
          <Field k="position" label="Position (Front/Rear, bumpers)" />
          <Field k="condition" label="Condition" />
          <Field k="price" label="Price" type="number" />
          <Field k="stock" label="Stock" type="number" />
          <Field k="sku" label="SKU" />
          <Field k="warranty" label="Warranty" />
          <div className="col-span-2"><Field k="images" label="Image URLs (comma separated)" /></div>
          <div className="col-span-2"><Field k="description" label="Description" textarea /></div>
        </div>
        <div className="mt-6 flex justify-end gap-3">
          <button onClick={onClose} className="px-5 py-2.5 border border-ink/20 text-sm uppercase tracking-widest" data-testid="cancel-edit">Cancel</button>
          <button onClick={() => onSave(p)} className="px-5 py-2.5 rounded-full bg-ink text-white text-sm uppercase tracking-widest" data-testid="save-product">Save</button>
        </div>
      </div>
    </div>
  );
}
