import { useEffect, useId, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { MagnifyingGlass, X, ArrowRight, KeyReturn } from "@phosphor-icons/react";
import { useCatalog, money } from "@/lib/catalog";
import { searchProducts, PART_LABEL_SINGULAR } from "@/lib/search";

export const SUGGESTIONS = ["2019 BMW 3 Series bumper", "C-Class headlight", "Audi Q5 2021", "G-Class bumper", "Rear bumper", "RS6 headlight"];

/** Cycles through example queries as a typed placeholder. */
function useTypedPlaceholder(active, items = SUGGESTIONS) {
  const [text, setText] = useState("");
  useEffect(() => {
    if (!active || window.matchMedia("(prefers-reduced-motion: reduce)").matches) { setText(items[0]); return; }
    let item = 0, ch = 0, deleting = false, t;
    const tick = () => {
      const word = items[item];
      ch += deleting ? -1 : 1;
      setText(word.slice(0, ch));
      if (!deleting && ch === word.length) { deleting = true; t = setTimeout(tick, 1600); return; }
      if (deleting && ch === 0) { deleting = false; item = (item + 1) % items.length; }
      t = setTimeout(tick, deleting ? 28 : 55);
    };
    t = setTimeout(tick, 600);
    return () => clearTimeout(t);
  }, [active, items]);
  return text;
}

/**
 * variant="hero": oversized pill with typed placeholder; results drop below.
 * variant="palette": used inside the command palette; results are inline.
 */
export default function SearchBox({ variant = "palette", autoFocus = false, onDone, className = "" }) {
  const nav = useNavigate();
  const { products } = useCatalog();
  const [q, setQ] = useState("");
  const [focused, setFocused] = useState(false);
  const [active, setActive] = useState(-1);
  const inputRef = useRef(null);
  const wrapRef = useRef(null);
  const listId = useId();
  const hero = variant === "hero";
  const typed = useTypedPlaceholder(hero && !focused && !q);

  const all = useMemo(() => (q.trim() ? searchProducts(products, q) : []), [products, q]);
  const results = all.slice(0, hero ? 5 : 7);
  const open = hero ? focused : true;

  useEffect(() => { setActive(-1); }, [q]);
  useEffect(() => {
    if (!hero) return;
    const onDown = (e) => { if (!wrapRef.current?.contains(e.target)) setFocused(false); };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [hero]);

  const finish = (path) => { setFocused(false); inputRef.current?.blur(); nav(path); onDone?.(); };
  const submitQuery = (text = q) => text.trim() && finish(`/shop?q=${encodeURIComponent(text.trim())}`);

  const onKeyDown = (e) => {
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(a + 1, results.length - 1)); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(a - 1, -1)); }
    else if (e.key === "Escape") { setFocused(false); inputRef.current?.blur(); onDone?.(); }
    else if (e.key === "Enter") {
      e.preventDefault();
      if (active >= 0 && results[active]) finish(`/product/${results[active].slug}`);
      else submitQuery();
    }
  };

  const list = (
    <div id={listId} role="listbox" data-lenis-prevent className={hero ? "absolute left-0 right-0 top-full z-40 mt-3 max-h-[60vh] overflow-y-auto rounded-[1.75rem] bg-white p-2 shadow-[0_30px_80px_-30px_rgba(15,20,30,0.45)] ring-1 ring-ink/5" : "mt-2 max-h-[55vh] overflow-y-auto"} data-testid="search-results">
      {!q.trim() ? (
        <div className="p-4">
          <p className="mb-3 text-xs text-ink-3">Popular searches</p>
          <div className="flex flex-wrap gap-2">
            {SUGGESTIONS.map((s) => (
              <button key={s} type="button" onClick={() => { setQ(s); inputRef.current?.focus(); }} className="rounded-full bg-canvas px-3.5 py-1.5 text-sm text-ink-2 transition-colors duration-300 hover:bg-ink hover:text-white">
                {s}
              </button>
            ))}
          </div>
        </div>
      ) : results.length === 0 ? (
        <p className="p-5 text-sm text-ink-2" data-testid="search-empty">
          Nothing matches "{q}" yet. Try a model (3 Series, C-Class, Q5), a chassis code (G20, W205) or a year.
        </p>
      ) : (
        <>
          {results.map((p, i) => (
            <button
              key={p.product_id}
              id={`${listId}-${i}`}
              role="option"
              aria-selected={active === i}
              type="button"
              onMouseEnter={() => setActive(i)}
              onClick={() => finish(`/product/${p.slug}`)}
              className={`flex w-full items-center gap-4 rounded-2xl p-2.5 text-left transition-colors duration-200 ${active === i ? "bg-canvas" : ""}`}
              data-testid={`search-result-${p.product_id}`}
            >
              <img src={p.images?.[0]} alt="" loading="lazy" className="h-12 w-16 shrink-0 rounded-xl object-cover" />
              <span className="min-w-0 flex-1">
                <span className="block truncate text-sm font-medium text-ink">{p.title}</span>
                <span className="block text-xs text-ink-3">{PART_LABEL_SINGULAR[p.part_type]} for {p.year_from}-{p.year_to}</span>
              </span>
              <span className="font-mono text-sm text-ink">{money(p.price)}</span>
            </button>
          ))}
          <button type="button" onClick={() => submitQuery()} className="mt-1 flex w-full items-center justify-between rounded-2xl px-4 py-3 text-sm text-ink-2 transition-colors hover:bg-canvas hover:text-ink" data-testid="search-see-all">
            <span>See all {all.length} result{all.length !== 1 && "s"} for "{q.trim()}"</span>
            <KeyReturn size={16} />
          </button>
        </>
      )}
    </div>
  );

  return (
    <div ref={wrapRef} className={`relative ${className}`} data-testid={hero ? "hero-search" : "search-box"}>
      <div className={hero
        ? "flex items-center gap-3 rounded-full bg-white py-2 pl-6 pr-2 shadow-[0_20px_60px_-25px_rgba(15,20,30,0.35)] ring-1 ring-ink/5 transition-shadow duration-500 focus-within:ring-2 focus-within:ring-signal/40"
        : "flex items-center gap-3 rounded-2xl bg-canvas px-4"}>
        <MagnifyingGlass size={hero ? 22 : 18} className="shrink-0 text-ink-3" />
        <input
          ref={inputRef}
          autoFocus={autoFocus}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onFocus={() => setFocused(true)}
          onKeyDown={onKeyDown}
          placeholder={hero ? typed || " " : "Search model, year or part"}
          aria-label="Search parts by model, year or part"
          role="combobox"
          aria-expanded={open}
          aria-controls={listId}
          aria-activedescendant={active >= 0 ? `${listId}-${active}` : undefined}
          className={`w-full bg-transparent text-ink outline-none placeholder:text-ink-3 ${hero ? "py-3 text-base md:text-lg" : "py-4 text-base"}`}
          data-testid={hero ? "hero-search-input" : "search-input"}
        />
        {q && (
          <button type="button" onClick={() => { setQ(""); inputRef.current?.focus(); }} aria-label="Clear search" className="grid h-8 w-8 shrink-0 place-items-center rounded-full text-ink-3 hover:bg-canvas hover:text-ink">
            <X size={14} />
          </button>
        )}
        {hero && (
          <button type="button" onClick={() => (q.trim() ? submitQuery() : inputRef.current?.focus())} aria-label="Search" className="group grid h-12 w-12 shrink-0 place-items-center rounded-full bg-ink text-white transition-transform duration-500 ease-spring hover:scale-105 active:scale-95" data-testid="hero-search-submit">
            <ArrowRight size={18} className="transition-transform duration-500 ease-spring group-hover:translate-x-0.5" />
          </button>
        )}
      </div>
      {open && list}
    </div>
  );
}
