import axios from "axios";
import catalog from "@/data/catalog.json";
import { filterProducts } from "@/lib/search";

export const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
export const API = `${BACKEND_URL}/api`;

// Without a backend (static preview builds) the catalog is served from the bundled
// demo data; account, checkout and admin calls reject with a friendly message.
export const DEMO_MODE = !BACKEND_URL;

const demoAdapter = async (config) => {
  const url = new URL(config.url, "http://demo.local");
  const params = { ...Object.fromEntries(url.searchParams), ...(config.params || {}) };
  const ok = (data) => ({ data, status: 200, statusText: "OK", headers: {}, config, request: {} });
  const fail = (status, detail) => {
    const err = new Error(detail);
    err.response = { status, data: { detail }, headers: {}, config };
    err.config = config;
    throw err;
  };

  if ((config.method || "get").toLowerCase() === "get") {
    if (url.pathname === "/products") {
      const limit = +params.limit || 60;
      return ok(filterProducts(catalog, params).slice(0, limit));
    }
    const m = url.pathname.match(/^\/products\/([^/]+)$/);
    if (m) {
      const p = catalog.find((x) => x.slug === decodeURIComponent(m[1]));
      return p ? ok(p) : fail(404, "Product not found");
    }
    if (url.pathname === "/auth/me") fail(401, "Not authenticated");
  }
  fail(503, "This is a design preview. Checkout and accounts go live at launch.");
};

export const api = DEMO_MODE
  ? axios.create({ baseURL: "", adapter: demoAdapter })
  : axios.create({ baseURL: API, withCredentials: true });
