import { useMemo } from "react";
import { Link, useParams, useSearchParams } from "react-router-dom";
import { motion, useReducedMotion } from "framer-motion";
import ProductCard, { ProductCardSkeleton } from "@/components/ProductCard";
import { Bezel, MaskHeadline, PillButton, Reveal, EASE } from "@/components/kit";
import { BRAND_META, brandFromSlug, useCatalog, vehicleTree } from "@/lib/catalog";
import { filterProducts, PART_LABELS } from "@/lib/search";

const ORDER = ["bumper", "headlight", "taillight"];

export default function Brand() {
  const { brand: slug } = useParams();
  const brand = brandFromSlug(slug);
  const [params, setParams] = useSearchParams();
  const { products, loading } = useCatalog();
  const reduce = useReducedMotion();

  const model = params.get("model") || "";
  const year = params.get("year") || "";
  const vehicles = useMemo(() => (brand ? vehicleTree(products)[brand] || [] : []), [products, brand]);
  const list = useMemo(() => (brand ? filterProducts(products, { brand, model, year }) : []), [products, brand, model, year]);
  const years = useMemo(() => {
    if (!vehicles.length) return [];
    const lo = Math.min(...vehicles.map((v) => v.year_from));
    const hi = Math.max(...vehicles.map((v) => v.year_to));
    return Array.from({ length: hi - lo + 1 }, (_, i) => hi - i);
  }, [vehicles]);

  if (!brand) {
    return (
      <div className="mx-auto max-w-7xl px-4 pb-24 pt-40 md:px-8" data-testid="brand-not-found">
        <h1 className="font-display text-5xl font-extrabold">We don't stock that marque yet.</h1>
        <PillButton to="/shop" className="mt-8">Browse all parts</PillButton>
      </div>
    );
  }
  const meta = BRAND_META[brand];
  const set = (k, v) => {
    const next = new URLSearchParams(params);
    if (v) next.set(k, v); else next.delete(k);
    setParams(next, { replace: true });
  };
  const counts = Object.fromEntries(ORDER.map((t) => [t, list.filter((p) => p.part_type === t).length]));

  return (
    <div data-testid={`brand-page-${meta.slug}`}>
      <section className="mx-auto grid grid-cols-1 max-w-7xl items-end gap-10 px-4 pb-14 pt-32 md:px-8 md:pt-40 lg:grid-cols-12">
        <div className="lg:col-span-5">
          <p className="font-mono text-xs text-ink-3">{meta.origin.toUpperCase()}</p>
          <MaskHeadline as="h1" lines={[[brand]]} className="mt-3 font-display text-7xl font-extrabold leading-[0.9] tracking-tighter md:text-9xl" />
          <p className="mt-6 max-w-md text-lg text-ink-2">{meta.blurb}</p>
          <div className="mt-8 flex flex-wrap gap-2">
            {ORDER.map((t) => (
              <a key={t} href={`#${t}`} onClick={(e) => { e.preventDefault(); document.getElementById(t)?.scrollIntoView({ behavior: "smooth", block: "start" }); }} className="rounded-full bg-white px-4 py-2 text-sm text-ink-2 ring-1 ring-ink/[0.06] transition-colors hover:bg-ink hover:text-white">
                {PART_LABELS[t]} <span className="font-mono text-xs opacity-60">{loading ? "" : counts[t]}</span>
              </a>
            ))}
          </div>
        </div>
        <motion.div className="lg:col-span-7" initial={reduce ? false : { opacity: 0, y: 40, scale: 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={{ duration: 1.3, ease: EASE }}>
          <Bezel radius="2.5rem" coreClassName="overflow-hidden p-1.5">
            <img src={meta.image} alt={`${brand} front end`} className="aspect-[16/10] w-full rounded-[2rem] object-cover" />
          </Bezel>
        </motion.div>
      </section>

      <div className="sticky top-[5.25rem] z-30 px-3 md:top-[6.25rem]">
        <div className="glass mx-auto flex max-w-5xl items-center gap-2 rounded-full p-1.5">
          <div className="no-scrollbar flex min-w-0 flex-1 gap-1 overflow-x-auto" role="group" aria-label="Filter by model">
            <button type="button" onClick={() => set("model", "")} className={`shrink-0 rounded-full px-4 py-2 text-sm transition-colors ${!model ? "bg-ink text-white" : "text-ink-2 hover:bg-ink/[0.05]"}`} data-testid="model-chip-all">All models</button>
            {vehicles.map((v) => {
              const val = `${v.model} ${v.chassis}`;
              return (
                <button key={val} type="button" onClick={() => set("model", model === val ? "" : val)} className={`shrink-0 whitespace-nowrap rounded-full px-4 py-2 text-sm transition-colors ${model === val ? "bg-ink text-white" : "text-ink-2 hover:bg-ink/[0.05]"}`} data-testid={`model-chip-${v.chassis}`}>
                  {v.label}
                </button>
              );
            })}
          </div>
          <label className="sr-only" htmlFor="brand-year">Year</label>
          <select id="brand-year" value={year} onChange={(e) => set("year", e.target.value)} className="shrink-0 rounded-full bg-white px-4 py-2 text-sm text-ink outline-none ring-1 ring-ink/10 focus:ring-signal" data-testid="brand-year">
            <option value="">Any year</option>
            {years.map((y) => <option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      </div>

      <div className="mx-auto max-w-7xl space-y-24 px-4 py-20 md:px-8">
        {loading ? (
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {Array.from({ length: 8 }, (_, i) => <ProductCardSkeleton key={i} />)}
          </div>
        ) : list.length === 0 ? (
          <Bezel radius="2rem" coreClassName="p-12 text-center" className="mx-auto max-w-xl">
            <p className="font-display text-2xl font-bold" data-testid="brand-empty">No {brand} parts for that model and year right now.</p>
            <PillButton onClick={() => setParams({}, { replace: true })} variant="light" className="mt-6">Clear filters</PillButton>
          </Bezel>
        ) : (
          ORDER.map((type) => {
            const items = list.filter((p) => p.part_type === type);
            if (!items.length) return null;
            return (
              <section key={type} id={type} className="scroll-mt-44" data-testid={`brand-${meta.slug}-${type}`}>
                <Reveal className="mb-10 flex items-end justify-between gap-6">
                  <h2 className="font-display text-5xl font-extrabold leading-none md:text-7xl">
                    {PART_LABELS[type]}<span className="ml-3 align-top font-mono text-base font-normal text-ink-3">{items.length}</span>
                  </h2>
                  <Link to={`/shop?brand=${brand}&part_type=${type}`} className="hidden text-sm text-ink-2 underline-offset-4 hover:text-ink hover:underline sm:inline">Open in shop</Link>
                </Reveal>
                <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
                  {items.map((p, i) => <Reveal key={p.product_id} delay={(i % 4) * 0.06}><ProductCard p={p} /></Reveal>)}
                </div>
              </section>
            );
          })
        )}
      </div>
    </div>
  );
}
