import { useRef } from "react";
import { motion, useMotionValue, useTransform } from "framer-motion";
import { ArrowsHorizontal } from "@phosphor-icons/react";

/**
 * Drag (or use arrow keys) to compare a weathered lens with a restored one.
 * The "before" side is the same photo with a haze filter: an illustration, not a real unit.
 */
export default function BeforeAfter({ src, alt }) {
  const box = useRef(null);
  const pos = useMotionValue(50);
  const clip = useTransform(pos, (v) => `inset(0 ${100 - v}% 0 0)`);
  const left = useTransform(pos, (v) => `${v}%`);

  const setFromPointer = (clientX) => {
    const r = box.current.getBoundingClientRect();
    pos.set(Math.min(100, Math.max(0, ((clientX - r.left) / r.width) * 100)));
  };
  const onDown = (e) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    setFromPointer(e.clientX);
  };

  return (
    <div
      ref={box}
      className="relative h-full min-h-[22rem] cursor-ew-resize select-none overflow-hidden rounded-[1.6rem] touch-pan-y"
      onPointerDown={onDown}
      onPointerMove={(e) => e.buttons === 1 && setFromPointer(e.clientX)}
      data-testid="before-after"
    >
      <img src={src} alt={`${alt}, restored`} className="absolute inset-0 h-full w-full object-cover" draggable={false} />
      <motion.img
        src={src}
        alt=""
        aria-hidden="true"
        draggable={false}
        style={{ clipPath: clip, filter: "sepia(0.55) saturate(0.45) contrast(0.7) brightness(1.15) blur(1.5px)" }}
        className="absolute inset-0 h-full w-full object-cover"
      />
      <span className="pointer-events-none absolute left-4 top-4 rounded-full bg-white/85 px-3 py-1 text-xs text-ink">Before</span>
      <span className="pointer-events-none absolute right-4 top-4 rounded-full bg-ink/80 px-3 py-1 text-xs text-white">After</span>
      {/* Full-width layer translated by pos% of its own width keeps the handle on the GPU. */}
      <motion.div style={{ x: left }} className="pointer-events-none absolute inset-0">
        <div className="absolute inset-y-0 left-0 w-px -translate-x-1/2 bg-white/90">
          <span className="absolute left-1/2 top-1/2 grid h-12 w-12 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full bg-white text-ink shadow-[0_10px_30px_rgba(0,0,0,0.3)]">
            <ArrowsHorizontal size={20} />
          </span>
        </div>
      </motion.div>
      <input
        type="range"
        min={0}
        max={100}
        defaultValue={50}
        onChange={(e) => pos.set(+e.target.value)}
        aria-label="Compare before and after restoration"
        className="absolute inset-x-0 bottom-0 h-full w-full cursor-ew-resize opacity-0"
        style={{ pointerEvents: "none" }}
        tabIndex={0}
      />
    </div>
  );
}
