import { useEffect, useState } from "react";
import { Link, useParams, useNavigate } from "react-router-dom";
import { motion, useReducedMotion } from "framer-motion";
import { ShieldCheck, CheckCircle, Truck, PaintBucket, Minus, Plus, Handbag, Lightning } from "@phosphor-icons/react";
import { toast } from "sonner";
import { api } from "@/lib/api";
import { useCart } from "@/lib/cart";
import ProductCard from "@/components/ProductCard";
import { Bezel, PillButton, Reveal, EASE } from "@/components/kit";
import { BRAND_META, money, useCatalog } from "@/lib/catalog";
import { PART_LABELS, PART_LABEL_SINGULAR } from "@/lib/search";

export default function ProductDetail() {
  const { slug } = useParams();
  const [p, setP] = useState(null);
  const [qty, setQty] = useState(1);
  const { add } = useCart();
  const nav = useNavigate();
  const { products } = useCatalog();
  const reduce = useReducedMotion();

  useEffect(() => {
    setP(null);
    setQty(1);
    api.get(`/products/${slug}`).then(({ data }) => setP(data)).catch(() => setP(false));
  }, [slug]);

  if (p === null) {
    return (
      <div className="mx-auto grid grid-cols-1 max-w-7xl gap-12 px-4 pb-20 pt-32 md:grid-cols-2 md:px-8 md:pt-40" aria-busy="true">
        <div className="aspect-square animate-pulse rounded-[2.5rem] bg-white/70" />
        <div className="space-y-4">
          <div className="h-4 w-40 animate-pulse rounded-full bg-white/70" />
          <div className="h-14 w-full animate-pulse rounded-2xl bg-white/70" />
          <div className="h-10 w-32 animate-pulse rounded-full bg-white/70" />
        </div>
      </div>
    );
  }
  if (p === false) {
    return (
      <div className="mx-auto max-w-7xl px-4 pb-20 pt-40 md:px-8" data-testid="not-found">
        <h1 className="font-display text-5xl font-extrabold">That part has moved on.</h1>
        <PillButton to="/shop" className="mt-8">Browse all parts</PillButton>
      </div>
    );
  }

  const meta = BRAND_META[p.brand];
  const related = products.filter((x) => x.product_id !== p.product_id && x.brand === p.brand && x.model === p.model && (x.chassis || "") === (p.chassis || "")).slice(0, 4);
  const vehicle = `${p.brand} ${p.model}${p.chassis ? ` ${p.chassis}` : ""}`;
  const part = PART_LABEL_SINGULAR[p.part_type] || p.part_type;
  const bumper = p.part_type === "bumper";
  const perks = [
    bumper
      ? { Icon: PaintBucket, t: "Primed, ready for paint", d: "Straightened and refinished. Your body shop matches the paint code." }
      : { Icon: Lightning, t: "Bench-tested", d: "Every function checked: low, high, DRL and indicators." },
    { Icon: ShieldCheck, t: `${p.warranty} warranty`, d: "Written warranty in the box." },
    { Icon: Truck, t: "Free tracked shipping", d: `Insured, ${bumper ? "crated, " : ""}3 to 7 business days.` },
  ];

  return (
    <div className="mx-auto max-w-7xl px-4 pb-16 pt-28 md:px-8 md:pt-36" data-testid="product-detail-page">
      <nav aria-label="Breadcrumb" className="mb-8 flex flex-wrap items-center gap-2 text-sm text-ink-3">
        <Link to="/shop" className="hover:text-ink">Shop</Link><span>/</span>
        {meta ? <Link to={`/brand/${meta.slug}`} className="hover:text-ink">{p.brand}</Link> : <span>{p.brand}</span>}<span>/</span>
        <Link to={`/shop?brand=${p.brand}&part_type=${p.part_type}`} className="hover:text-ink">{PART_LABELS[p.part_type] || p.part_type}</Link>
      </nav>

      <div className="grid grid-cols-1 gap-10 md:grid-cols-12 lg:gap-16">
        <motion.div className="self-start md:sticky md:top-28 md:col-span-7" initial={reduce ? false : { opacity: 0, y: 30, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={{ duration: 1.1, ease: EASE }}>
          <Bezel radius="2.5rem" coreClassName="overflow-hidden p-1.5">
            <img src={(p.images || [])[0]} alt={p.title} className="aspect-[4/3.4] w-full rounded-[2rem] object-cover" data-testid="product-image" />
          </Bezel>
        </motion.div>

        <motion.div className="md:col-span-5" initial={reduce ? false : { opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1.1, delay: 0.1, ease: EASE }}>
          <div className="flex flex-wrap items-center gap-2 text-sm">
            <span className="text-ink-2">{p.position ? `${p.position} ` : ""}{part}</span>
            <span className={`rounded-full px-3 py-0.5 text-xs ${p.condition === "Refurbished" ? "bg-signal-soft text-signal" : "bg-white text-ink-2"}`} data-testid="product-condition">{p.condition}</span>
          </div>
          <h1 className="mt-4 font-display text-4xl font-extrabold leading-[1] tracking-tight md:text-5xl" data-testid="product-title">{p.title}</h1>
          <p className="mt-6 font-display text-5xl font-extrabold" data-testid="product-price">{money(p.price)}<span className="ml-2 font-mono text-sm font-normal text-ink-3">USD</span></p>
          <p className="mt-6 leading-relaxed text-ink-2">{p.description}</p>

          <div className="mt-8 grid grid-cols-2 gap-3">
            <div className="rounded-[1.5rem] bg-white p-5 ring-1 ring-ink/[0.05]">
              <p className="text-xs text-ink-3">Fits</p>
              <p className="mt-1 font-medium">{vehicle}</p>
              <p className="mt-1 font-mono text-xs text-ink-3">{p.year_from}-{p.year_to}</p>
            </div>
            <div className="rounded-[1.5rem] bg-white p-5 ring-1 ring-ink/[0.05]">
              <p className="text-xs text-ink-3">Stock</p>
              <p className="mt-1 font-medium">{p.stock > 0 ? `${p.stock} available` : "Out of stock"}</p>
              <p className="mt-1 font-mono text-xs text-ink-3">{p.sku}</p>
            </div>
          </div>

          <div className="mt-8 flex items-center gap-3">
            <div className="flex items-center rounded-full bg-white p-1 ring-1 ring-ink/[0.06]">
              <button onClick={() => setQty(Math.max(1, qty - 1))} className="grid h-11 w-11 place-items-center rounded-full hover:bg-canvas" aria-label="Decrease quantity" data-testid="qty-decrease"><Minus size={16} /></button>
              <input value={qty} onChange={(e) => setQty(Math.max(1, +e.target.value || 1))} className="w-10 bg-transparent text-center font-mono outline-none" aria-label="Quantity" data-testid="qty-input" />
              <button onClick={() => setQty(qty + 1)} className="grid h-11 w-11 place-items-center rounded-full hover:bg-canvas" aria-label="Increase quantity" data-testid="qty-increase"><Plus size={16} /></button>
            </div>
            <PillButton
              onClick={() => { add(p, qty); toast.success("Added to cart", { description: p.title }); }}
              disabled={p.stock <= 0}
              icon={Handbag}
              className="flex-1"
              testid="add-to-cart-btn"
            >
              Add to cart
            </PillButton>
          </div>
          <PillButton onClick={() => { add(p, qty); nav("/cart"); }} disabled={p.stock <= 0} variant="signal" className="mt-3 w-full" testid="buy-now-btn">Buy now</PillButton>

          <div className="mt-10 space-y-5">
            {perks.map(({ Icon, t, d }) => (
              <div key={t} className="flex gap-4">
                <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white text-signal ring-1 ring-ink/[0.05]"><Icon size={18} /></span>
                <div><p className="font-medium">{t}</p><p className="text-sm text-ink-2">{d}</p></div>
              </div>
            ))}
            <div className="flex gap-4">
              <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-white text-signal ring-1 ring-ink/[0.05]"><CheckCircle size={18} /></span>
              <div><p className="font-medium">OEM part, not aftermarket</p><p className="text-sm text-ink-2">Original manufacturer part, restored to spec.</p></div>
            </div>
          </div>
        </motion.div>
      </div>

      {related.length > 0 && (
        <section className="mt-32" data-testid="related-products">
          <Reveal><h2 className="mb-10 font-display text-4xl font-extrabold md:text-6xl">More for the {p.model}{p.chassis ? ` ${p.chassis}` : ""}.</h2></Reveal>
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-4">
            {related.map((r, i) => <Reveal key={r.product_id} delay={i * 0.06}><ProductCard p={r} /></Reveal>)}
          </div>
        </section>
      )}
    </div>
  );
}
