import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { SlidersHorizontal, X, MagnifyingGlass } from "@phosphor-icons/react";
import { Bezel, MaskHeadline } from "@/components/kit";
import ProductCard, { ProductCardSkeleton } from "@/components/ProductCard";
import { BRANDS, useCatalog, vehicleTree } from "@/lib/catalog";
import { filterProducts, PART_LABELS } from "@/lib/search";

const CONDITIONS = ["Refurbished", "New", "Used"];
const SORTS = { relevance: "Best match", "price-asc": "Price, low to high", "price-desc": "Price, high to low", newest: "Newest models" };

export default function Shop() {
  const [params, setParams] = useSearchParams();
  const { products, loading } = useCatalog();
  const [showFilters, setShowFilters] = useState(false);

  const get = (k) => params.get(k) || "";
  const brand = get("brand"), part_type = get("part_type"), condition = get("condition");
  const model = get("model"), year = get("year"), q = get("q"), sort = get("sort") || "relevance";
  const [text, setText] = useState(q);
  useEffect(() => setText(q), [q]);

  const tree = useMemo(() => vehicleTree(products), [products]);
  const models = useMemo(() => (brand ? tree[brand] || [] : []), [tree, brand]);
  const years = useMemo(() => {
    const src = brand ? models : Object.values(tree).flat();
    if (!src.length) return [];
    const lo = Math.min(...src.map((v) => v.year_from));
    const hi = Math.max(...src.map((v) => v.year_to));
    return Array.from({ length: hi - lo + 1 }, (_, i) => hi - i);
  }, [brand, models, tree]);

  const results = useMemo(() => {
    const out = filterProducts(products, { brand, part_type, condition, model, year, q });
    if (sort === "price-asc") return [...out].sort((a, b) => a.price - b.price);
    if (sort === "price-desc") return [...out].sort((a, b) => b.price - a.price);
    if (sort === "newest") return [...out].sort((a, b) => b.year_to - a.year_to || b.year_from - a.year_from);
    return out;
  }, [products, brand, part_type, condition, model, year, q, sort]);

  const setFilter = (k, v, extra = {}) => {
    const next = new URLSearchParams(params);
    if (v) next.set(k, v); else next.delete(k);
    Object.entries(extra).forEach(([ek, ev]) => (ev ? next.set(ek, ev) : next.delete(ek)));
    setParams(next);
  };
  const submitText = (e) => { e.preventDefault(); setFilter("q", text.trim()); };

  const active = [
    brand && { k: "brand", l: brand },
    model && { k: "model", l: model },
    year && { k: "year", l: year },
    part_type && { k: "part_type", l: PART_LABELS[part_type] || part_type },
    condition && { k: "condition", l: condition },
    q && { k: "q", l: `"${q}"` },
  ].filter(Boolean);

  const heading = q
    ? `Results for "${q}"`
    : !brand && !model && !year && !part_type ? "All parts" : [year, brand, model, part_type ? PART_LABELS[part_type] : "parts"].filter(Boolean).join(" ");

  const Opt = ({ on, onClick, children, testid }) => (
    <button
      type="button"
      data-testid={testid}
      onClick={onClick}
      aria-pressed={on}
      className={`rounded-full px-4 py-2 text-left text-sm transition-colors duration-300 ${on ? "bg-ink text-white" : "bg-canvas text-ink-2 hover:bg-ink/[0.08] hover:text-ink"}`}
    >{children}</button>
  );

  return (
    <div className="mx-auto max-w-7xl px-4 pb-16 pt-32 md:px-8 md:pt-40" data-testid="shop-page">
      <MaskHeadline key={heading} lines={[[heading.charAt(0).toUpperCase() + heading.slice(1) + "."]]} className="font-display text-5xl font-extrabold leading-[0.95] tracking-tighter md:text-7xl" />

      <form onSubmit={submitText} className="mt-10 flex max-w-2xl items-center gap-3 rounded-full bg-white py-1.5 pl-6 pr-1.5 shadow-[0_20px_50px_-30px_rgba(15,20,30,0.35)] ring-1 ring-ink/5 focus-within:ring-2 focus-within:ring-signal/40" role="search">
        <MagnifyingGlass size={20} className="shrink-0 text-ink-3" />
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Try 2019 3 Series bumper, W205 headlight, Q5"
          aria-label="Search by model, year or part"
          className="w-full bg-transparent py-3 text-base text-ink placeholder:text-ink-3 outline-none"
          data-testid="shop-search-input"
        />
        <button type="submit" className="shrink-0 rounded-full bg-ink px-5 py-3 text-sm font-medium text-white transition-transform duration-500 ease-spring active:scale-95">Search</button>
      </form>

      {active.length > 0 && (
        <div className="mt-5 flex flex-wrap items-center gap-2" data-testid="active-filters">
          {active.map((f) => (
            <button key={f.k} type="button" onClick={() => setFilter(f.k, "", f.k === "brand" ? { model: "" } : {})} className="inline-flex items-center gap-1.5 rounded-full bg-white px-3.5 py-1.5 text-xs text-ink ring-1 ring-ink/10 hover:ring-ink/30">
              {f.l} <X size={12} />
            </button>
          ))}
          <button type="button" onClick={() => setParams({})} className="ml-1 text-xs text-ink-3 hover:text-ink">Clear all</button>
        </div>
      )}

      <div className="mt-10 grid grid-cols-1 md:grid-cols-12 gap-10">
        <button type="button" onClick={() => setShowFilters(!showFilters)} className="inline-flex w-fit items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm ring-1 ring-ink/10 md:hidden" data-testid="toggle-filters">
          <SlidersHorizontal size={16} /> {showFilters ? "Hide filters" : "Filters"}
        </button>

        <aside className={`${showFilters ? "block" : "hidden"} md:block md:col-span-3`} data-testid="shop-filters">
          <Bezel radius="2rem" coreClassName="space-y-8 p-5 md:sticky">
          <fieldset>
            <legend className="text-xs text-ink-3 mb-3">Part</legend>
            <div className="grid grid-cols-2 md:grid-cols-1 gap-2">
              <Opt testid="filter-type-all" on={!part_type} onClick={() => setFilter("part_type", "")}>All parts</Opt>
              {Object.entries(PART_LABELS).map(([id, l]) => (
                <Opt testid={`filter-type-${id}`} key={id} on={part_type === id} onClick={() => setFilter("part_type", id)}>{l}</Opt>
              ))}
            </div>
          </fieldset>
          <fieldset>
            <legend className="text-xs text-ink-3 mb-3">Make</legend>
            <div className="grid grid-cols-2 md:grid-cols-1 gap-2">
              <Opt testid="filter-brand-all" on={!brand} onClick={() => setFilter("brand", "", { model: "" })}>All makes</Opt>
              {BRANDS.map((b) => (
                <Opt testid={`filter-brand-${b.toLowerCase()}`} key={b} on={brand === b} onClick={() => setFilter("brand", b, { model: "" })}>{b}</Opt>
              ))}
            </div>
          </fieldset>
          {models.length > 0 && (
            <fieldset>
              <legend className="text-xs text-ink-3 mb-3">{brand} model</legend>
              <div className="flex flex-wrap gap-2">
                {models.map((v) => {
                  const val = `${v.model} ${v.chassis}`;
                  return (
                    <button key={val} type="button" onClick={() => setFilter("model", model === val ? "" : val)} aria-pressed={model === val}
                      className={`rounded-full px-3 py-1.5 text-xs transition-colors ${model === val ? "bg-ink text-white" : "bg-canvas text-ink-2 hover:bg-ink/[0.08]"}`}
                      data-testid={`filter-model-${v.chassis}`}>{v.label}</button>
                  );
                })}
              </div>
            </fieldset>
          )}
          <div className="flex flex-col gap-2">
            <label htmlFor="filter-year" className="text-xs text-ink-3">Year</label>
            <select id="filter-year" value={year} onChange={(e) => setFilter("year", e.target.value)} className="rounded-full bg-canvas px-4 py-2.5 text-sm text-ink outline-none focus:ring-2 focus:ring-signal/40" data-testid="filter-year">
              <option value="">Any year</option>
              {years.map((y) => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <fieldset>
            <legend className="text-xs text-ink-3 mb-3">Condition</legend>
            <div className="grid grid-cols-2 md:grid-cols-1 gap-2">
              <Opt testid="filter-cond-all" on={!condition} onClick={() => setFilter("condition", "")}>Any condition</Opt>
              {CONDITIONS.map((c) => (
                <Opt testid={`filter-cond-${c.toLowerCase()}`} key={c} on={condition === c} onClick={() => setFilter("condition", c)}>{c}</Opt>
              ))}
            </div>
          </fieldset>
          </Bezel>
        </aside>

        <div className="md:col-span-9" data-testid="shop-grid">
          <div className="flex items-center justify-between gap-5 mb-6">
            <p className="text-sm text-ink-3" aria-live="polite">{loading ? "Loading parts" : `${results.length} part${results.length !== 1 ? "s" : ""}`}</p>
            <label className="flex items-center gap-2 text-sm text-ink-3">
              <span className="hidden sm:inline">Sort</span>
              <select value={sort} onChange={(e) => setFilter("sort", e.target.value === "relevance" ? "" : e.target.value)} className="rounded-full bg-white px-4 py-2 text-sm text-ink outline-none ring-1 ring-ink/10 focus:ring-signal" data-testid="sort-select">
                {Object.entries(SORTS).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
              </select>
            </label>
          </div>
          {loading ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
              {Array.from({ length: 6 }, (_, i) => <ProductCardSkeleton key={i} />)}
            </div>
          ) : results.length === 0 ? (
            <Bezel radius="2rem" coreClassName="p-12 text-center">
              <div data-testid="empty-state">
                <p className="font-display text-3xl font-extrabold">No parts match yet.</p>
                <p className="mx-auto mt-3 max-w-md text-sm text-ink-2">Try a wider year, a different model, or search by chassis code like G20, W205 or B9.</p>
                <button type="button" onClick={() => setParams({})} className="mt-6 rounded-full bg-ink px-6 py-3 text-sm font-medium text-white">Clear filters</button>
              </div>
            </Bezel>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
              {results.map((p) => <ProductCard key={p.product_id} p={p} />)}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
