import { useEffect, useRef, useState } from "react";
import { useSearchParams, Link } from "react-router-dom";
import { api } from "@/lib/api";
import { useCart } from "@/lib/cart";
import { Check, CircleNotch } from "@phosphor-icons/react";

export default function CheckoutSuccess() {
  const [params] = useSearchParams();
  const sessionId = params.get("session_id");
  const [status, setStatus] = useState({ payment_status: "pending", status: "pending" });
  const [done, setDone] = useState(false);
  const { clear } = useCart();
  const attempts = useRef(0);

  useEffect(() => {
    if (!sessionId) { setDone(true); return; }
    let timer;
    const poll = async () => {
      try {
        const { data } = await api.get(`/checkout/status/${sessionId}`);
        setStatus(data);
        if (data.payment_status === "paid") {
          setDone(true); clear(); return;
        }
        if (data.status === "expired" || attempts.current >= 8) { setDone(true); return; }
        attempts.current += 1;
        timer = setTimeout(poll, 2000);
      } catch {
        if (attempts.current >= 5) { setDone(true); return; }
        attempts.current += 1;
        timer = setTimeout(poll, 2000);
      }
    };
    poll();
    return () => timer && clearTimeout(timer);
  }, [sessionId, clear]);

  const paid = status.payment_status === "paid";

  return (
    <div className="max-w-2xl mx-auto px-4 md:px-8 pt-40 pb-20 text-center" data-testid="success-page">
      {!done ? (
        <>
          <CircleNotch size={48} strokeWidth={1.2} className="animate-spin mx-auto text-signal" />
          <h1 className="font-display text-3xl font-extrabold mt-6">Confirming your payment</h1>
          <p className="text-ink-3 mt-2 text-sm">Please don't close this page.</p>
        </>
      ) : paid ? (
        <>
          <div className="inline-flex items-center justify-center w-16 h-16 border border-signal/40 rounded-full glow-amber">
            <Check size={28} strokeWidth={1.5} className="text-signal" />
          </div>
          <h1 className="font-display text-4xl md:text-5xl font-extrabold mt-6" data-testid="success-title">Payment successful.</h1>
          <p className="text-ink-2 mt-3">Your order is confirmed. We'll send tracking details to your email.</p>
          <div className="mt-10 flex gap-3 justify-center">
            <Link to="/account" className="rounded-full bg-ink text-white px-6 py-3 text-sm uppercase tracking-widest font-medium">My orders</Link>
            <Link to="/shop" className="border border-ink/20 px-6 py-3 text-sm uppercase tracking-widest font-medium">Continue shopping</Link>
          </div>
        </>
      ) : (
        <>
          <h1 className="font-display text-3xl font-extrabold">Payment not completed</h1>
          <p className="text-ink-3 mt-2">If you were charged, contact support. Otherwise, try again.</p>
          <Link to="/cart" className="inline-block mt-6 rounded-full bg-ink text-white px-6 py-3 text-sm uppercase tracking-widest font-medium">Back to cart</Link>
        </>
      )}
    </div>
  );
}
