import { motion, useReducedMotion } from "framer-motion";
import { Star } from "@phosphor-icons/react";
import { Eyebrow, EASE } from "@/components/kit";

// TODO(before launch): these are SAMPLE reviews. Replace with real, verifiable customer
// reviews and set REVIEWS_ARE_PLACEHOLDERS to false. Do not publish them as genuine.
export const REVIEWS_ARE_PLACEHOLDERS = true;

const REVIEWS = [
  { name: "Daniel R.", car: "BMW 3 Series G20", part: "Adaptive LED headlight", rating: 5, text: "Plugged straight in, every function worked including the cornering lights. Lens looks better than my other side." },
  { name: "Priya S.", car: "Mercedes C-Class W205", part: "Rear bumper cover", rating: 5, text: "Arrived crated with zero marks. Body shop said the prep was clean and only needed a scuff before paint." },
  { name: "Marco T.", car: "Audi A4 B9", part: "Matrix LED headlight", rating: 5, text: "Dealer wanted more than double. Needed coding after install, which they warned me about up front." },
  { name: "Hannah K.", car: "BMW X5 G05", part: "Taillight, left", rating: 4, text: "Perfect fit and all segments lit. Took six days to arrive, but it was well boxed and tracked the whole way." },
  { name: "Owen M.", car: "Mercedes E-Class W213", part: "Multibeam headlight", rating: 5, text: "Low, high, DRL and indicators all worked out of the box. Written warranty was in with the light." },
  { name: "Leila A.", car: "Audi RS6 C8", part: "Front bumper, RS", rating: 5, text: "Sensor cut-outs lined up first try. Tabs and clips were all intact, which is rare for used bumpers." },
  { name: "Chris B.", car: "BMW M4 G82", part: "Front bumper cover", rating: 5, text: "Chassis-code search made it easy to be sure. Fitted the same weekend it arrived." },
  { name: "Sofia L.", car: "Mercedes GLE W167", part: "Taillight, right", rating: 5, text: "Indistinguishable from the original on the other side. Gaskets were new." },
  { name: "James P.", car: "Audi A6 C8", part: "LED headlight", rating: 4, text: "Ordered the wrong side by mistake. Return was painless and the swap shipped quickly." },
];

const initials = (n) => n.split(" ").map((w) => w[0]).join("").slice(0, 2);

function ReviewCard({ r }) {
  return (
    <figure className="rounded-[1.75rem] bg-white p-6 ring-1 ring-ink/[0.06] shadow-[0_20px_40px_-30px_rgba(15,20,30,0.35)]">
      <div className="flex gap-0.5 text-signal" aria-label={`${r.rating} out of 5 stars`}>
        {Array.from({ length: 5 }).map((_, i) => (
          <Star key={i} size={14} weight={i < r.rating ? "fill" : "regular"} className={i < r.rating ? "" : "text-ink/20"} />
        ))}
      </div>
      <blockquote className="mt-4 text-[15px] leading-relaxed text-ink">“{r.text}”</blockquote>
      <figcaption className="mt-5 flex items-center gap-3">
        <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-canvas font-display text-sm font-bold text-ink-2">{initials(r.name)}</span>
        <span className="min-w-0">
          <span className="block text-sm font-medium">{r.name}</span>
          <span className="block truncate font-mono text-[11px] text-ink-3">{r.car} · {r.part}</span>
        </span>
      </figcaption>
    </figure>
  );
}

/** One looping column. Content is doubled so a -50% translate wraps seamlessly. */
function Column({ items, duration, reverse, className = "" }) {
  return (
    <div className={`review-col ${className}`}>
      <div className="review-col-track flex flex-col gap-5" style={{ animationDuration: `${duration}s`, animationDirection: reverse ? "reverse" : "normal" }}>
        {[...items, ...items].map((r, i) => (
          <div key={i} aria-hidden={i >= items.length}>
            <ReviewCard r={r} />
          </div>
        ))}
      </div>
    </div>
  );
}

// Each column shows every review from a different starting point, so hiding columns on
// smaller screens never drops a review.
const rotate = (arr, n) => [...arr.slice(n), ...arr.slice(0, n)];

/** Vertical kinetic testimonials, adapted from 21st.dev "Testimonials Vertical Marquee" (scrollxui). */
export default function Reviews() {
  const reduce = useReducedMotion();
  const title = "Fitted, and still fitted.".split(" ");
  const avg = (REVIEWS.reduce((s, r) => s + r.rating, 0) / REVIEWS.length).toFixed(1);

  return (
    <section className="mx-auto max-w-7xl px-4 py-28 md:px-8 md:py-36" data-testid="reviews">
      <div className="grid grid-cols-1 gap-12 lg:grid-cols-12">
        <div className="lg:col-span-4">
          <div className="lg:sticky lg:top-32">
            <Eyebrow>Owners</Eyebrow>
            <h2 className="mt-5 font-display text-5xl font-extrabold leading-[0.95] md:text-6xl">
              {title.map((w, i) => (
                <motion.span
                  key={i}
                  className="mr-[0.22em] inline-block last:mr-0"
                  initial={reduce ? false : { opacity: 0, y: 12, filter: "blur(6px)" }}
                  whileInView={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6, delay: i * 0.08, ease: EASE }}
                >
                  {w}
                </motion.span>
              ))}
            </h2>
            <p className="mt-6 flex items-baseline gap-3">
              <span className="font-display text-5xl font-extrabold">{avg}</span>
              <span className="text-ink-2">average from {REVIEWS.length} reviews</span>
            </p>
            {REVIEWS_ARE_PLACEHOLDERS && (
              <p className="mt-4 inline-block rounded-full bg-signal-soft px-3 py-1 font-mono text-[11px] text-signal" data-testid="reviews-sample-note">
                SAMPLE REVIEWS, FOR DESIGN PREVIEW
              </p>
            )}
          </div>
        </div>
        <div className="review-wall grid h-[40rem] grid-cols-1 gap-5 overflow-hidden md:grid-cols-2 lg:col-span-8 xl:grid-cols-3">
          <Column items={REVIEWS} duration={46} />
          <Column items={rotate(REVIEWS, 3)} duration={58} reverse className="hidden md:block" />
          <Column items={rotate(REVIEWS, 6)} duration={52} className="hidden xl:block" />
        </div>
      </div>
    </section>
  );
}
