import { useRef } from "react";
import { Link } from "react-router-dom";
import { motion, useReducedMotion, useScroll, useTransform } from "framer-motion";
import { ShieldCheck, MagnifyingGlassPlus, Wrench, Lightning, Package, ArrowUpRight } from "@phosphor-icons/react";
import SearchBox, { SUGGESTIONS } from "@/components/SearchBox";
import VehicleFinder from "@/components/VehicleFinder";
import MarqueGallery from "@/components/BrandShowcase";
import BeforeAfter from "@/components/BeforeAfter";
import Reviews from "@/components/Reviews";
import ProofStats from "@/components/ProofStats";
import Faq from "@/components/Faq";
import ProductCard, { ProductCardSkeleton } from "@/components/ProductCard";
import { Bezel, Eyebrow, MaskHeadline, PillButton, Reveal, EASE } from "@/components/kit";
import { useCatalog, money } from "@/lib/catalog";

const U = (id, w = 1600) => `https://images.unsplash.com/photo-${id}?auto=format&fit=crop&w=${w}&q=80`;
const HERO_MAIN = U("1617531653332-bd46c24f2068", 1400);
const HERO_DETAIL = U("1549207107-2704df6b92ab", 900);
const POPULAR = [...SUGGESTIONS, "W213 E-Class", "M4 G82 bumper", "Audi A4 B9", "X5 taillight", "2017 headlight"];

const PROCESS = [
  { Icon: MagnifyingGlassPlus, t: "Inspect", d: "Every part is checked against OEM fitment and graded. Cracked mounts and failed electronics never make the shelf.", tone: "bg-white text-ink", sub: "text-ink-2" },
  { Icon: Wrench, t: "Restore", d: "Bumpers are straightened, refinished and primed. Lenses are resurfaced and UV-coated, seals and gaskets replaced.", tone: "bg-ink text-white", sub: "text-white/65" },
  { Icon: Lightning, t: "Test", d: "Lights are bench-tested segment by segment: low, high, DRL, indicators and adaptive functions.", tone: "bg-signal text-white", sub: "text-white/80" },
  { Icon: Package, t: "Ship", d: "Bumpers ship crated, lights double-boxed. Tracked and insured, with a written warranty in the box.", tone: "bg-[#dfe3e8] text-ink", sub: "text-ink-2" },
];

function Hero({ featured }) {
  const ref = useRef(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ["start start", "end start"] });
  const yMain = useTransform(scrollYProgress, [0, 1], [0, reduce ? 0 : 120]);
  const yDetail = useTransform(scrollYProgress, [0, 1], [0, reduce ? 0 : -80]);
  const fade = useTransform(scrollYProgress, [0, 0.8], [1, reduce ? 1 : 0.3]);

  return (
    <section ref={ref} className="relative overflow-hidden">
      {/* Soft studio light behind the hero. */}
      <div className="pointer-events-none absolute -right-40 -top-40 h-[42rem] w-[42rem] rounded-full bg-[radial-gradient(circle,rgba(255,255,255,1)_0%,rgba(255,255,255,0)_70%)]" aria-hidden="true" />
      <div className="pointer-events-none absolute -bottom-60 left-1/4 h-[36rem] w-[36rem] rounded-full bg-[radial-gradient(circle,hsl(10_87%_45%/0.10)_0%,transparent_70%)]" aria-hidden="true" />

      <div className="relative mx-auto grid grid-cols-1 min-h-[100dvh] max-w-7xl items-center gap-12 px-4 pb-16 pt-28 md:px-8 lg:grid-cols-12 lg:pt-24">
        <motion.div style={{ opacity: fade }} className="lg:col-span-6">
          <motion.div initial={reduce ? false : { opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.8, ease: EASE }}>
            <Eyebrow>Refurbished OEM for BMW, Mercedes, Audi</Eyebrow>
          </motion.div>
          <MaskHeadline
            testid="hero-title"
            delay={0.15}
            className="mt-6 font-display text-[3.4rem] font-extrabold leading-[0.92] tracking-tighter sm:text-7xl xl:text-[6.5rem]"
            lines={[["Bumpers", "&"], ["lights,"], [{ em: "restored." }]]}
          />
          <motion.p
            initial={reduce ? false : { opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, delay: 0.55, ease: EASE }}
            className="mt-7 max-w-md text-lg leading-relaxed text-ink-2"
          >
            Search by model, chassis or year. Every part tested and warrantied, at about half the dealer price.
          </motion.p>
          <motion.div initial={reduce ? false : { opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.9, delay: 0.7, ease: EASE }} className="mt-9 max-w-xl lg:max-w-[28rem] xl:max-w-[30rem]">
            <SearchBox variant="hero" />
          </motion.div>
        </motion.div>

        {/* Z-axis cascade: main photo tray with a detail card overlapping it. */}
        <div className="relative lg:col-span-6">
          <motion.div style={{ y: yMain }} initial={reduce ? false : { opacity: 0, scale: 0.94 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 1.4, delay: 0.2, ease: EASE }}>
            <Bezel radius="2.5rem" className="lg:rotate-[1.5deg]" coreClassName="overflow-hidden p-1.5">
              <img src={HERO_MAIN} alt="Red BMW M4 front end" fetchpriority="high" className="aspect-[4/5] w-full rounded-[2rem] object-cover sm:aspect-[5/4] lg:aspect-[4/5]" />
            </Bezel>
          </motion.div>
          {featured && (
            <motion.div
              style={{ y: yDetail }}
              initial={reduce ? false : { opacity: 0, y: 40 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 1.2, delay: 0.8, ease: EASE }}
              className="relative mt-4 lg:absolute lg:-bottom-10 lg:-left-6 lg:mt-0 lg:w-[17rem] xl:-left-10"
            >
              <Link to={`/product/${featured.slug}`} className="group block lg:-rotate-[3deg]" data-testid="hero-featured">
                <Bezel radius="1.75rem" coreClassName="flex items-center gap-4 p-2 pr-5 lg:block lg:p-2">
                  <img src={HERO_DETAIL} alt="" className="h-20 w-24 shrink-0 rounded-[1.25rem] object-cover lg:h-36 lg:w-full" />
                  <div className="min-w-0 lg:px-3 lg:pb-3 lg:pt-4">
                    <p className="font-mono text-[11px] text-ink-3">FITS {featured.year_from}-{featured.year_to}</p>
                    <p className="mt-1 truncate font-display text-base font-bold lg:whitespace-normal">{featured.title}</p>
                    <div className="mt-2 flex items-center justify-between">
                      <span className="font-display text-xl font-extrabold">{money(featured.price)}</span>
                      <span className="grid h-8 w-8 place-items-center rounded-full bg-canvas transition-transform duration-500 ease-spring group-hover:-translate-y-0.5 group-hover:translate-x-0.5"><ArrowUpRight size={14} /></span>
                    </div>
                  </div>
                </Bezel>
              </Link>
            </motion.div>
          )}
        </div>
      </div>
    </section>
  );
}

function PopularMarquee() {
  return (
    <section className="overflow-hidden border-y border-ink/[0.06] bg-surface py-5" aria-label="Popular searches">
      <div className="marquee-track flex w-max gap-3">
        {[...POPULAR, ...POPULAR].map((s, i) => (
          <Link key={i} to={`/shop?q=${encodeURIComponent(s)}`} className="shrink-0 rounded-full bg-white px-5 py-2.5 text-sm text-ink-2 ring-1 ring-ink/[0.06] transition-colors duration-300 hover:bg-ink hover:text-white" tabIndex={i >= POPULAR.length ? -1 : 0}>
            {s}
          </Link>
        ))}
      </div>
    </section>
  );
}

function RestoreBento({ products }) {
  const count = (t) => products.filter((p) => p.part_type === t).length;
  return (
    <section className="mx-auto max-w-7xl px-4 py-28 md:px-8 md:py-36" data-testid="part-types">
      <Reveal>
        <h2 className="font-display text-5xl font-extrabold leading-[0.95] md:text-7xl">What we restore.</h2>
      </Reveal>
      <div className="mt-14 grid grid-cols-1 gap-5 md:grid-cols-12 md:grid-rows-2">
        <Reveal className="md:col-span-7 md:row-span-2">
          <Bezel radius="2.25rem" coreClassName="flex h-full flex-col p-2">
            <BeforeAfter src={U("1514316454349-750a7fd3da3a", 1400)} alt="Mercedes LED headlight" />
            <div className="flex flex-wrap items-end justify-between gap-4 p-5 md:p-6">
              <div>
                <h3 className="font-display text-3xl font-extrabold md:text-4xl">Headlights</h3>
                <p className="mt-2 max-w-sm text-ink-2">Hazy, yellowed lenses resurfaced to clear. LED, Matrix and laser units, every function tested.</p>
              </div>
              <PillButton to="/shop?part_type=headlight" testid="tile-headlight">{count("headlight")} headlights</PillButton>
            </div>
          </Bezel>
        </Reveal>
        {[
          { type: "bumper", label: "Bumpers", copy: "Front and rear covers, straightened and primed for paint.", img: U("1580273916550-e323be2ae537", 1100), delay: 0.08 },
          { type: "taillight", label: "Taillights", copy: "Every LED segment tested, fresh gaskets fitted.", img: "https://images.pexels.com/photos/221325/pexels-photo-221325.jpeg?auto=compress&cs=tinysrgb&w=1100", delay: 0.16 },
        ].map((t) => (
          <Reveal key={t.type} delay={t.delay} className="md:col-span-5">
            <Link to={`/shop?part_type=${t.type}`} className="group block h-full" data-testid={`tile-${t.type}`}>
              <Bezel radius="2.25rem" coreClassName="grid h-full grid-cols-5 gap-2 p-2">
                <div className="col-span-2 overflow-hidden rounded-[1.6rem]">
                  <img src={t.img} alt="" loading="lazy" className="h-full min-h-[11rem] w-full object-cover transition-transform duration-1000 ease-expo group-hover:scale-110" />
                </div>
                <div className="col-span-3 flex flex-col justify-between p-4">
                  <div>
                    <h3 className="font-display text-3xl font-extrabold">{t.label}</h3>
                    <p className="mt-2 text-sm text-ink-2">{t.copy}</p>
                  </div>
                  <p className="mt-4 inline-flex items-center gap-2 font-mono text-xs text-signal">
                    {count(t.type)} IN STOCK <ArrowUpRight size={12} className="transition-transform duration-500 ease-spring group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                  </p>
                </div>
              </Bezel>
            </Link>
          </Reveal>
        ))}
      </div>
    </section>
  );
}

function ProcessStack() {
  return (
    <section className="mx-auto max-w-7xl px-4 pb-28 md:px-8 md:pb-36">
      <div className="grid grid-cols-1 gap-12 lg:grid-cols-12">
        <div className="lg:col-span-4">
          <div className="lg:sticky lg:top-32">
            <Eyebrow>How it works</Eyebrow>
            <h2 className="mt-5 font-display text-5xl font-extrabold leading-[0.95] md:text-6xl">Four checks before it ships.</h2>
            <p className="mt-5 max-w-sm text-ink-2">Refurbished means restored and proven, not just cleaned.</p>
          </div>
        </div>
        <div className="space-y-6 lg:col-span-8">
          {PROCESS.map(({ Icon, t, d, tone, sub }, i) => (
            <div key={t} className="sticky" style={{ top: `calc(7rem + ${i * 1.5}rem)` }}>
              <div className={`flex min-h-[18rem] flex-col justify-between rounded-[2.25rem] p-8 shadow-[0_30px_60px_-30px_rgba(15,20,30,0.35)] md:p-12 ${tone}`}>
                <Icon size={40} weight="light" />
                <div className="mt-10 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
                  <h3 className="font-display text-6xl font-extrabold leading-none md:text-8xl">{t}</h3>
                  <p className={`max-w-sm text-base leading-relaxed ${sub}`}>{d}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function FreshRail({ products, loading }) {
  const picks = products.filter((p) => p.part_type !== "taillight").slice().sort((a, b) => b.year_to - a.year_to || b.price - a.price).slice(0, 8);
  return (
    <section className="py-24" data-testid="best-sellers">
      <div className="mx-auto mb-10 flex max-w-7xl items-end justify-between gap-6 px-4 md:px-8">
        <Reveal><h2 className="font-display text-5xl font-extrabold leading-[0.95] md:text-6xl">Latest models.</h2></Reveal>
        <PillButton to="/shop?sort=newest" variant="light" className="hidden sm:inline-flex">Shop all</PillButton>
      </div>
      <div className="no-scrollbar flex snap-x snap-mandatory gap-5 overflow-x-auto px-4 pb-4 md:px-[max(2rem,calc((100vw-80rem)/2+2rem))]">
        {(loading ? Array.from({ length: 4 }) : picks).map((p, i) => (
          <div key={p?.product_id || i} className="w-[78vw] shrink-0 snap-start sm:w-[22rem]">
            {p ? <ProductCard p={p} /> : <ProductCardSkeleton />}
          </div>
        ))}
      </div>
    </section>
  );
}

function Promise() {
  const items = [
    { Icon: ShieldCheck, t: "12-month warranty", d: "Written warranty on every refurbished part. Six months on used." },
    { Icon: Package, t: "30-day returns", d: "Wrong fit? Send it back within 30 days." },
  ];
  return (
    <section className="mx-auto max-w-7xl px-4 md:px-8">
      <Reveal>
        <Bezel radius="2.5rem" coreClassName="grid grid-cols-1 gap-10 p-8 md:grid-cols-2 md:p-14">
          <h2 className="font-display text-4xl font-extrabold leading-[1] md:text-6xl">OEM quality, without the dealer markup.</h2>
          <div className="space-y-8">
            {items.map(({ Icon, t, d }) => (
              <div key={t} className="flex gap-5">
                <span className="grid h-12 w-12 shrink-0 place-items-center rounded-full bg-signal-soft text-signal"><Icon size={22} /></span>
                <div>
                  <h3 className="font-display text-xl font-bold">{t}</h3>
                  <p className="mt-1 text-ink-2">{d}</p>
                </div>
              </div>
            ))}
            <PillButton to="/shop" variant="signal">Browse all parts</PillButton>
          </div>
        </Bezel>
      </Reveal>
    </section>
  );
}

export default function Home() {
  const { products, loading } = useCatalog();
  const featured = products.find((p) => p.slug === "bmw-3-series-g20-adaptive-led-headlight");

  return (
    <div data-testid="home-page">
      <Hero featured={featured} />
      <PopularMarquee />
      <section className="mx-auto max-w-7xl px-4 pt-28 md:px-8 md:pt-36" data-testid="finder-section">
        <Reveal>
          <h2 className="mb-12 max-w-3xl font-display text-5xl font-extrabold leading-[0.95] md:text-7xl">Find your exact fit.</h2>
        </Reveal>
        <Reveal delay={0.1}><VehicleFinder /></Reveal>
      </section>
      <MarqueGallery products={products} />
      <RestoreBento products={products} />
      <ProcessStack />
      <ProofStats products={products} />
      <FreshRail products={products} loading={loading} />
      <Reviews />
      <Promise />
      <Faq />
    </div>
  );
}
