import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { AnimatePresence, motion } from "framer-motion";
import { BRANDS, useCatalog, vehicleTree, money } from "@/lib/catalog";
import { filterProducts, PART_LABELS } from "@/lib/search";
import { Bezel, PillButton, EASE } from "@/components/kit";

function Chip({ on, onClick, children, testid, size = "md" }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={on}
      data-testid={testid}
      className={`rounded-full transition-[background-color,color,transform] duration-500 ease-spring active:scale-[0.97] ${size === "lg" ? "px-6 py-3 font-display text-lg font-bold md:text-xl" : "px-4 py-2 text-sm"} ${on ? "bg-ink text-white" : "bg-canvas text-ink-2 hover:bg-ink/[0.08] hover:text-ink"}`}
    >
      {children}
    </button>
  );
}

export default function VehicleFinder() {
  const { products } = useCatalog();
  const tree = useMemo(() => vehicleTree(products), [products]);
  const [brand, setBrand] = useState("BMW");
  const [vehicle, setVehicle] = useState("");
  const [year, setYear] = useState(null);
  const [part, setPart] = useState("");

  const vehicles = useMemo(() => tree[brand] || [], [tree, brand]);
  const chosen = vehicles.find((v) => `${v.model} ${v.chassis}` === vehicle);
  const range = useMemo(() => {
    const src = chosen ? [chosen] : vehicles;
    if (!src.length) return [2012, 2024];
    return [Math.min(...src.map((v) => v.year_from)), Math.max(...src.map((v) => v.year_to))];
  }, [chosen, vehicles]);
  const y = year && year >= range[0] && year <= range[1] ? year : null;

  const matches = useMemo(() => filterProducts(products, { brand, model: vehicle, year: y || "", part_type: part }), [products, brand, vehicle, y, part]);
  const qs = new URLSearchParams(Object.entries({ brand, model: vehicle, year: y || "", part_type: part }).filter(([, v]) => v));

  return (
    <Bezel radius="2.5rem" coreClassName="grid grid-cols-1 gap-10 p-5 md:grid-cols-12 md:p-10" className="w-full">
      <div className="min-w-0 space-y-8 md:col-span-7">
        <div>
          <p className="mb-3 text-sm text-ink-3">Make</p>
          <div className="flex flex-wrap gap-2">
            {BRANDS.map((b) => (
              <Chip key={b} size="lg" on={brand === b} onClick={() => { setBrand(b); setVehicle(""); setYear(null); }} testid={`finder-brand-${b.toLowerCase()}`}>{b}</Chip>
            ))}
          </div>
        </div>
        <div>
          <p className="mb-3 text-sm text-ink-3">Model</p>
          <div className="flex flex-wrap gap-2">
            <Chip on={!vehicle} onClick={() => setVehicle("")} testid="finder-model-any">Any {brand}</Chip>
            {vehicles.map((v) => {
              const val = `${v.model} ${v.chassis}`;
              return <Chip key={val} on={vehicle === val} onClick={() => setVehicle(vehicle === val ? "" : val)} testid={`finder-model-${v.chassis}`}>{v.label}</Chip>;
            })}
          </div>
        </div>
        <div>
          <div className="mb-1 flex min-h-8 items-center justify-between gap-3">
            <label htmlFor="finder-year" className="text-sm text-ink-3">Model year</label>
            {y ? (
              <span className="flex items-center gap-2">
                <span className="font-mono text-sm text-ink" data-testid="finder-year-value">{y}</span>
                <button type="button" onClick={() => setYear(null)} className="rounded-full bg-canvas px-3 py-1 text-xs text-ink-2 transition-colors hover:bg-ink hover:text-white" data-testid="finder-year-clear">
                  Clear
                </button>
              </span>
            ) : (
              <span className="text-sm text-ink-3" data-testid="finder-year-value">Any year <span className="text-ink-3/70">· drag to pick</span></span>
            )}
          </div>
          {/* Idle (no year chosen): hollow thumb parked mid-track so it doesn't read as a selection. */}
          <input
            id="finder-year"
            type="range"
            className={`year-range ${y ? "" : "year-range--idle"}`}
            min={range[0]}
            max={range[1]}
            step={1}
            value={y || Math.round((range[0] + range[1]) / 2)}
            onChange={(e) => setYear(+e.target.value)}
            onPointerUp={(e) => !y && setYear(+e.currentTarget.value)}
            aria-valuetext={y ? String(y) : "Any year"}
            data-testid="finder-year"
          />
          <div className="flex justify-between font-mono text-[11px] text-ink-3"><span>{range[0]}</span><span>{range[1]}</span></div>
        </div>
        <div>
          <p className="mb-3 text-sm text-ink-3">Part</p>
          <div className="flex flex-wrap gap-2">
            <Chip on={!part} onClick={() => setPart("")} testid="finder-part-all">Everything</Chip>
            {Object.entries(PART_LABELS).map(([k, l]) => <Chip key={k} on={part === k} onClick={() => setPart(k)} testid={`finder-part-${k}`}>{l}</Chip>)}
          </div>
        </div>
      </div>

      <div className="flex min-w-0 flex-col justify-between rounded-[1.75rem] bg-canvas p-6 md:col-span-5 md:p-8" aria-live="polite">
        <div>
          <p className="text-sm text-ink-3">Parts that fit</p>
          <div className="relative h-[7.5rem] overflow-hidden md:h-[9rem]">
            <AnimatePresence mode="popLayout" initial={false}>
              <motion.p
                key={matches.length}
                initial={{ y: "100%", opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: "-100%", opacity: 0 }}
                transition={{ duration: 0.6, ease: EASE }}
                className="absolute font-display text-[7rem] font-extrabold leading-none tracking-tighter text-ink md:text-[8.5rem]"
                data-testid="finder-count"
              >
                {matches.length}
              </motion.p>
            </AnimatePresence>
          </div>
          <div className="mt-4 space-y-2">
            {matches.slice(0, 3).map((p) => (
              <Link key={p.product_id} to={`/product/${p.slug}`} className="flex items-center gap-3 rounded-2xl bg-white p-2 pr-4 transition-transform duration-500 ease-spring hover:translate-x-1">
                <img src={p.images[0]} alt="" className="h-10 w-14 rounded-xl object-cover" loading="lazy" />
                <span className="min-w-0 flex-1 truncate text-sm text-ink">{p.title.replace(`${p.brand} `, "")}</span>
                <span className="font-mono text-xs text-ink-2">{money(p.price)}</span>
              </Link>
            ))}
            {matches.length === 0 && <p className="text-sm text-ink-2">Nothing for that combination yet. Try another year or part.</p>}
          </div>
        </div>
        <PillButton to={`/shop?${qs}`} variant="signal" className="mt-8 w-full" testid="finder-submit">
          Show {matches.length} part{matches.length !== 1 && "s"}
        </PillButton>
      </div>
    </Bezel>
  );
}
