import { useEffect, useRef, useState } from "react";
import { animate, useInView, useReducedMotion } from "framer-motion";
import { Reveal, EASE } from "@/components/kit";

/** Counts up from 0 to `to` the first time it scrolls into view. */
function CountUp({ to, pad = 0 }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, amount: 0.6 });
  const reduce = useReducedMotion();
  const [n, setN] = useState(reduce ? to : 0);

  useEffect(() => {
    if (!inView || reduce) { setN(to); return; }
    const c = animate(0, to, { duration: 1.6, ease: EASE, onUpdate: (v) => setN(Math.round(v)) });
    return () => c.stop();
  }, [inView, to, reduce]);

  return <span ref={ref} className="tabular-nums">{String(n).padStart(pad, "0")}</span>;
}

/** Proof band. Every figure is derived from the live catalog, so it stays true as stock changes. */
export default function ProofStats({ products }) {
  if (!products?.length) return null;
  const units = products.reduce((s, p) => s + (p.stock || 0), 0);
  const fits = new Set(products.map((p) => `${p.brand}|${p.model}|${p.chassis || ""}`)).size;
  const from = Math.min(...products.map((p) => p.year_from));
  const to = Math.max(...products.map((p) => p.year_to));

  const stats = [
    { v: units, label: "Parts on the shelf", sub: "Inspected and ready to ship" },
    { v: fits, label: "Models and chassis", sub: "BMW, Mercedes and Audi" },
    { v: to - from + 1, label: "Model years", sub: `${from} to ${to}` },
    { v: 12, pad: 2, label: "Month warranty", sub: "On refurbished and new" },
  ];

  return (
    <section className="mx-auto max-w-7xl px-4 pb-28 md:px-8 md:pb-36" data-testid="proof-stats">
      <Reveal>
        <div className="grid grid-cols-2 overflow-hidden rounded-[2.25rem] bg-ink text-white lg:grid-cols-4">
          {stats.map((s, i) => (
            <div key={s.label} className={`p-7 md:p-10 ${i % 2 ? "border-l border-white/10" : ""} ${i >= 2 ? "border-t border-white/10 lg:border-t-0" : ""} ${i === 2 ? "lg:border-l" : ""}`}>
              <p className="font-display text-5xl font-extrabold leading-none md:text-7xl">
                <CountUp to={s.v} pad={s.pad} />
              </p>
              <p className="mt-4 text-sm font-medium">{s.label}</p>
              <p className="mt-1 font-mono text-[11px] text-white/55">{s.sub}</p>
            </div>
          ))}
        </div>
      </Reveal>
    </section>
  );
}
