import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useCart } from "@/lib/cart";
import { api } from "@/lib/api";
import { toast } from "sonner";

export default function Checkout() {
  const { items, subtotal, clear } = useCart();
  const nav = useNavigate();
  const [provider, setProvider] = useState("stripe");
  const [loading, setLoading] = useState(false);
  const [shipping, setShipping] = useState({ name: "", address: "", city: "", zip: "", country: "" });

  if (items.length === 0) {
    return <div className="max-w-3xl mx-auto px-4 md:px-8 pt-40 pb-20" data-testid="empty-checkout"><p className="text-ink-2">Your cart is empty.</p></div>;
  }

  const submit = async () => {
    setLoading(true);
    try {
      const payload = {
        items: items.map((i) => ({ product_id: i.product_id, qty: i.qty })),
        origin_url: window.location.origin,
        shipping,
        provider,
      };
      if (provider === "stripe") {
        const { data } = await api.post("/checkout/stripe", payload);
        window.location.href = data.url;
      } else {
        const { data } = await api.post("/checkout/paypal", payload);
        window.location.href = data.approve_url;
      }
    } catch (e) {
      toast.error(e?.response?.data?.detail || "Checkout failed");
      setLoading(false);
    }
  };

  const Field = ({ k, label, type = "text" }) => (
    <div>
      <label className="text-xs uppercase tracking-widest text-ink-3">{label}</label>
      <input
        type={type}
        value={shipping[k]}
        onChange={(e) => setShipping({ ...shipping, [k]: e.target.value })}
        className="mt-1 w-full bg-white border border-ink/10 px-4 py-3 text-sm focus:border-signal outline-none"
        data-testid={`ship-${k}`}
      />
    </div>
  );

  return (
    <div className="max-w-6xl mx-auto px-4 md:px-8 pt-32 pb-16 md:pt-40" data-testid="checkout-page">
      <h1 className="font-display text-5xl md:text-6xl font-extrabold mb-10">Checkout.</h1>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        <div className="md:col-span-2 space-y-8">
          <section>
            <h2 className="font-display text-2xl font-bold mb-4">Shipping</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <Field k="name" label="Full name" />
              <Field k="address" label="Address" />
              <Field k="city" label="City" />
              <Field k="zip" label="Postal code" />
              <Field k="country" label="Country" />
            </div>
          </section>
          <section>
            <h2 className="font-display text-2xl font-bold mb-4">Payment</h2>
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => setProvider("stripe")} className={`p-4 border text-left ${provider === "stripe" ? "border-signal bg-signal-soft" : "border-ink/10"}`} data-testid="pay-stripe">
                <p className="font-display text-lg font-bold">Stripe</p>
                <p className="text-xs text-ink-3">Cards, Apple/Google Pay</p>
              </button>
              <button onClick={() => setProvider("paypal")} className={`p-4 border text-left ${provider === "paypal" ? "border-signal bg-signal-soft" : "border-ink/10"}`} data-testid="pay-paypal">
                <p className="font-display text-lg font-bold">PayPal</p>
                <p className="text-xs text-ink-3">PayPal balance / card</p>
              </button>
            </div>
          </section>
        </div>
        <aside className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-6 h-fit">
          <h3 className="font-display text-xl font-bold mb-4">Order</h3>
          {items.map((i) => (
            <div key={i.product_id} className="flex justify-between text-sm mb-2">
              <span className="text-ink-2 line-clamp-1 pr-2">{i.title} × {i.qty}</span>
              <span>${(i.price * i.qty).toFixed(2)}</span>
            </div>
          ))}
          <div className="border-t border-ink/10 mt-4 pt-4 flex justify-between font-display text-xl font-bold"><span>Total</span><span className="text-signal">${subtotal.toFixed(2)}</span></div>
          <button onClick={submit} disabled={loading} className="mt-6 w-full rounded-full bg-ink text-white py-4 text-sm uppercase tracking-widest font-medium hover:bg-ink/90 disabled:opacity-50" data-testid="place-order-btn">
            {loading ? "Processing" : `Pay with ${provider === "stripe" ? "Stripe" : "PayPal"}`}
          </button>
          <p className="text-xs text-ink-3 mt-3">You'll be redirected to {provider === "stripe" ? "Stripe" : "PayPal"} to complete payment securely.</p>
        </aside>
      </div>
    </div>
  );
}
