import { createContext, useContext, useEffect, useState } from "react";

const CartCtx = createContext(null);
const KEY = "autolux_cart_v1";

export function CartProvider({ children }) {
  const [items, setItems] = useState(() => {
    try { return JSON.parse(localStorage.getItem(KEY)) || []; } catch { return []; }
  });

  useEffect(() => { localStorage.setItem(KEY, JSON.stringify(items)); }, [items]);

  const add = (product, qty = 1) => {
    setItems((prev) => {
      const idx = prev.findIndex((i) => i.product_id === product.product_id);
      if (idx >= 0) {
        const copy = [...prev];
        copy[idx] = { ...copy[idx], qty: copy[idx].qty + qty };
        return copy;
      }
      return [...prev, { product_id: product.product_id, title: product.title, price: product.price, image: (product.images || [])[0], qty }];
    });
  };
  const remove = (pid) => setItems((p) => p.filter((i) => i.product_id !== pid));
  const setQty = (pid, qty) => setItems((p) => p.map((i) => i.product_id === pid ? { ...i, qty: Math.max(1, qty) } : i));
  const clear = () => setItems([]);
  const count = items.reduce((s, i) => s + i.qty, 0);
  const subtotal = items.reduce((s, i) => s + i.qty * i.price, 0);

  return <CartCtx.Provider value={{ items, add, remove, setQty, clear, count, subtotal }}>{children}</CartCtx.Provider>;
}

export const useCart = () => useContext(CartCtx);
