import { useEffect, useState } from "react";
import { useAuth } from "@/lib/auth";
import { api } from "@/lib/api";
import { Link } from "react-router-dom";

export default function Account() {
  const { user, loading, login } = useAuth();
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    if (user) api.get("/orders/mine").then(({ data }) => setOrders(data)).catch(() => {});
  }, [user]);

  if (loading) return <div className="max-w-5xl mx-auto px-4 md:px-8 pt-40 pb-20 text-ink-3">Loading</div>;
  if (!user) {
    return (
      <div className="max-w-md mx-auto px-4 md:px-8 pt-40 pb-20 text-center" data-testid="account-login">
        <h1 className="font-display text-4xl font-extrabold">Sign in.</h1>
        <p className="text-ink-2 mt-3">Continue with Google to view your orders.</p>
        <button onClick={login} className="mt-8 w-full rounded-full bg-ink text-white py-4 text-sm uppercase tracking-widest font-medium" data-testid="google-signin-btn">
          Continue with Google
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-4 md:px-8 pt-32 pb-16 md:pt-40" data-testid="account-page">
      <div className="flex items-center gap-4 mb-10">
        {user.picture && <img src={user.picture} className="w-12 h-12 rounded-full border border-ink/10" alt="" />}
        <div>
          <p className="text-xs uppercase tracking-widest text-signal">Account</p>
          <h1 className="font-display text-3xl font-extrabold">{user.name}</h1>
          <p className="text-ink-3 text-sm">{user.email}</p>
        </div>
      </div>

      <h2 className="font-display text-2xl font-bold mb-4">Orders</h2>
      {orders.length === 0 ? (
        <div className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-10 text-center text-ink-3" data-testid="no-orders">
          No orders yet. <Link to="/shop" className="text-signal underline">Start shopping</Link>.
        </div>
      ) : (
        <div className="space-y-3">
          {orders.map((o) => (
            <div key={o.order_id} className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-5 flex items-center justify-between" data-testid={`order-${o.order_id}`}>
              <div>
                <p className="font-mono text-xs text-ink-3">{o.order_id}</p>
                <p className="font-display font-bold">${o.total.toFixed(2)} · {o.items.length} item(s)</p>
                <p className="text-xs text-ink-3">{new Date(o.created_at).toLocaleString()}</p>
              </div>
              <span className={`text-xs uppercase tracking-widest px-3 py-1 border ${o.status === "paid" ? "border-signal/40 text-signal" : "border-ink/10 text-ink-2"}`}>{o.status}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
