import { Link } from "react-router-dom";
import { motion, useReducedMotion } from "framer-motion";
import { ArrowUpRight } from "@phosphor-icons/react";

export const EASE = [0.16, 1, 0.3, 1];

/** Heavy fade-up with a soft blur as the element enters the viewport. */
export function Reveal({ children, delay = 0, y = 40, className = "", as = "div", amount = 0.2 }) {
  const reduce = useReducedMotion();
  const M = motion[as];
  return (
    <M
      className={className}
      initial={reduce ? false : { opacity: 0, y, filter: "blur(8px)" }}
      whileInView={{ opacity: 1, y: 0, filter: "blur(0px)" }}
      viewport={{ once: true, amount }}
      transition={{ duration: 0.9, delay, ease: EASE }}
    >
      {children}
    </M>
  );
}

/** Headline where each word rises out of its own mask. Pass lines as an array; wrap emphasis in {em: "word"}. */
export function MaskHeadline({ lines, className = "", delay = 0, as = "h1", testid }) {
  const reduce = useReducedMotion();
  const Tag = as;
  let i = 0;
  return (
    <Tag className={className} data-testid={testid}>
      {lines.map((line, li) => (
        <span key={li} className="block">
          {line.map((w, wi) => {
            const idx = i++;
            const text = typeof w === "string" ? w : w.em;
            return (
              <span key={wi} className="inline-block overflow-hidden align-bottom pb-[0.08em] -mb-[0.08em] mr-[0.22em] last:mr-0">
                <motion.span
                  className={`inline-block ${typeof w === "string" ? "" : "text-signal"}`}
                  initial={reduce ? false : { y: "110%" }}
                  animate={{ y: "0%" }}
                  transition={{ duration: 1.1, delay: delay + idx * 0.07, ease: EASE }}
                >
                  {text}
                </motion.span>
              </span>
            );
          })}
        </span>
      ))}
    </Tag>
  );
}

export function Eyebrow({ children, className = "" }) {
  return (
    <span className={`inline-flex items-center rounded-full bg-white/70 px-3 py-1 text-[10px] font-medium uppercase tracking-[0.2em] text-ink-2 ring-1 ring-ink/10 ${className}`}>
      {children}
    </span>
  );
}

/** Pill CTA with the trailing icon nested in its own circle. */
export function PillButton({ to, onClick, children, variant = "ink", type = "button", className = "", icon: Icon = ArrowUpRight, testid, disabled }) {
  const styles = {
    ink: "bg-ink text-white hover:bg-ink/90",
    signal: "bg-signal text-white hover:bg-signal/90",
    light: "bg-white text-ink ring-1 ring-ink/10 hover:ring-ink/25",
  }[variant];
  const dot = { ink: "bg-white/15", signal: "bg-white/20", light: "bg-ink/[0.06]" }[variant];
  const inner = (
    <>
      <span className="pl-2">{children}</span>
      <span className={`grid h-9 w-9 place-items-center rounded-full ${dot} transition-transform duration-500 ease-spring group-hover:translate-x-0.5 group-hover:-translate-y-px group-hover:scale-105`}>
        <Icon size={16} weight="regular" />
      </span>
    </>
  );
  const cls = `group inline-flex items-center justify-between gap-3 rounded-full py-1.5 pl-5 pr-1.5 text-sm font-medium whitespace-nowrap transition-[transform,background-color,box-shadow] duration-500 ease-spring active:scale-[0.98] disabled:opacity-40 disabled:pointer-events-none ${styles} ${className}`;
  if (to) return <Link to={to} className={cls} data-testid={testid}>{inner}</Link>;
  return <button type={type} onClick={onClick} className={cls} data-testid={testid} disabled={disabled}>{inner}</button>;
}

/** Outer machined tray + inner core with concentric radius. */
export function Bezel({ children, className = "", coreClassName = "", radius = "2rem" }) {
  return (
    <div className={`bezel ${className}`} style={{ borderRadius: radius }}>
      <div className={`bezel-core h-full ${coreClassName}`} style={{ borderRadius: `calc(${radius} - 0.375rem)` }}>
        {children}
      </div>
    </div>
  );
}
