// Vehicle-aware product search shared by the header search, the shop page and the
// offline demo catalog. Mirrors `_matches_query` in backend/server.py.

const STOPWORDS = new Set(["for", "the", "a", "an", "of", "my", "and", "with", "to", "in", "year", "model", "part", "parts", "car"]);

const BRAND_ALIASES = {
  BMW: ["bmw", "bimmer", "beemer"],
  Mercedes: ["mercedes", "benz", "merc", "mb", "amg"],
  Audi: ["audi"],
};

const PART_ALIASES = {
  bumper: ["bumper", "fascia", "bumper cover"],
  headlight: ["headlight", "headlamp", "light", "front light"],
  taillight: ["taillight", "taillamp", "light", "rear light"],
};

/** Lowercase, collapse "3 series"/"3-series" -> "3series", "c class" -> "cclass", "head light" -> "headlight". */
export function normalize(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/mercedes-benz/g, "mercedes")
    .replace(/[-_/,.()]/g, " ")
    .replace(/\b(\d)\s*(series)\b/g, "$1series")
    .replace(/\b([a-z]{1,3})\s+(class)\b/g, "$1class")
    .replace(/\bamg\s+gt\b/g, "amggt")
    .replace(/\b(head|tail)\s+(light|lamp)/g, "$1$2")
    .replace(/\s+/g, " ")
    .trim();
}

function stem(token) {
  return token.length > 3 && token.endsWith("s") && !/\d/.test(token) ? token.slice(0, -1) : token;
}

export function parseQuery(q) {
  const tokens = normalize(q).split(" ").filter(Boolean);
  const years = [];
  const words = [];
  for (const t of tokens) {
    if (/^(19|20)\d{2}$/.test(t)) years.push(+t);
    else if (/^'\d{2}$/.test(t)) years.push(2000 + +t.slice(1));
    else if (!STOPWORDS.has(t)) words.push(stem(t));
  }
  return { years, words };
}

function haystack(p) {
  if (p.__hay) return p.__hay;
  const parts = [
    p.title, p.brand, p.model, p.chassis, p.part_type, p.position, p.condition, p.sku,
    ...(BRAND_ALIASES[p.brand] || []),
    ...(PART_ALIASES[p.part_type] || []),
  ];
  const words = normalize(parts.join(" ")).split(" ");
  Object.defineProperty(p, "__hay", { value: words, enumerable: false });
  return words;
}

/** Every word must prefix-match a word in the product; every year must fall in its fitment range. */
export function matchesQuery(p, parsed) {
  const { years, words } = parsed;
  if (years.some((y) => y < p.year_from || y > p.year_to)) return false;
  const hay = haystack(p);
  return words.every((w) => hay.some((h) => h.startsWith(w)));
}

export function searchProducts(products, q) {
  const parsed = parseQuery(q);
  if (!parsed.years.length && !parsed.words.length) return products;
  const titleWords = (p) => normalize(p.title).split(" ");
  return products
    .filter((p) => matchesQuery(p, parsed))
    .map((p) => ({ p, score: parsed.words.filter((w) => titleWords(p).some((t) => t.startsWith(w))).length }))
    .sort((a, b) => b.score - a.score)
    .map(({ p }) => p);
}

/** Apply the same filters the API accepts: brand, part_type, condition, model, year, q. */
export function filterProducts(products, params = {}) {
  let out = products.filter((p) => p.active !== false);
  if (params.brand) out = out.filter((p) => p.brand === params.brand);
  if (params.part_type) out = out.filter((p) => p.part_type === params.part_type);
  if (params.condition) out = out.filter((p) => p.condition === params.condition);
  if (params.model) {
    const m = normalize(params.model);
    out = out.filter((p) => normalize(`${p.model} ${p.chassis || ""}`).includes(m));
  }
  if (params.year) {
    const y = +params.year;
    out = out.filter((p) => y >= p.year_from && y <= p.year_to);
  }
  if (params.q) out = searchProducts(out, params.q);
  return out;
}

export const PART_LABELS = { bumper: "Bumpers", headlight: "Headlights", taillight: "Taillights" };
export const PART_LABEL_SINGULAR = { bumper: "Bumper", headlight: "Headlight", taillight: "Taillight" };
