import { useLayoutEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { motion, useReducedMotion, useScroll, useSpring, useTransform } from "framer-motion";
import { ArrowRight } from "@phosphor-icons/react";
import { BRANDS, BRAND_META, money } from "@/lib/catalog";
import { PART_LABELS } from "@/lib/search";
import { PillButton } from "@/components/kit";

const THEMES = {
  BMW: { core: "bg-white", ink: "text-ink", sub: "text-ink-2", row: "bg-canvas hover:bg-ink hover:text-white", btn: "ink" },
  Mercedes: { core: "bg-ink", ink: "text-white", sub: "text-white/60", row: "bg-white/[0.07] text-white hover:bg-white hover:text-ink", btn: "light" },
  Audi: { core: "bg-gradient-to-br from-[#dfe3e8] via-white to-[#cfd5dc]", ink: "text-ink", sub: "text-ink-2", row: "bg-white/80 hover:bg-ink hover:text-white", btn: "signal" },
};

function PartList({ brand, type, products, theme }) {
  const items = products.filter((p) => p.brand === brand && p.part_type === type);
  return (
    <div data-testid={`rail-${BRAND_META[brand].slug}-${type}`}>
      <Link to={`/shop?brand=${brand}&part_type=${type}`} className={`group mb-3 flex items-baseline justify-between ${theme.ink}`}>
        <span className="font-display text-2xl font-bold">{PART_LABELS[type]}</span>
        <span className={`inline-flex items-center gap-1 font-mono text-xs ${theme.sub}`}>
          {items.length} IN STOCK <ArrowRight size={12} className="transition-transform duration-500 ease-spring group-hover:translate-x-1" />
        </span>
      </Link>
      <div className="space-y-1.5">
        {items.slice(0, 3).map((p) => (
          <Link key={p.product_id} to={`/product/${p.slug}`} className={`flex items-center gap-3 rounded-2xl p-1.5 pr-4 transition-colors duration-300 ${theme.row}`}>
            <img src={p.images[0]} alt="" loading="lazy" className="h-10 w-14 shrink-0 rounded-xl object-cover" />
            <span className="min-w-0 flex-1 truncate text-sm">{p.model} {p.chassis} {p.position ? `${p.position} ` : ""}{type === "bumper" ? "bumper" : p.title.split(p.chassis)[1]?.trim()}</span>
            <span className="font-mono text-xs opacity-80">{money(p.price)}</span>
          </Link>
        ))}
      </div>
    </div>
  );
}

function BrandPanel({ brand, products, className = "" }) {
  const meta = BRAND_META[brand];
  const t = THEMES[brand];
  return (
    <article className={`bezel rounded-[2.5rem] ${className}`} data-testid={`brand-section-${meta.slug}`}>
      <div className={`grid h-full grid-cols-1 overflow-hidden rounded-[calc(2.5rem-0.375rem)] md:grid-cols-2 ${t.core}`}>
        <Link to={`/brand/${meta.slug}`} className="group relative m-2 min-h-[16rem] overflow-hidden rounded-[2rem]" data-testid={`brand-${meta.slug}`} aria-label={`All ${brand} parts`}>
          <img src={meta.image} alt={`${brand} front end`} loading="lazy" className="absolute inset-0 h-full w-full object-cover transition-transform duration-1000 ease-expo group-hover:scale-105" />
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/0 to-transparent" />
          <h3 className="absolute bottom-5 left-6 font-display text-6xl font-extrabold leading-none text-white md:text-7xl lg:text-8xl">{brand}</h3>
        </Link>
        <div className="flex min-w-0 flex-col gap-7 p-6 md:p-8 lg:p-10">
          <p className={`max-w-sm text-base ${t.sub}`}>{meta.blurb}</p>
          <PartList brand={brand} type="bumper" products={products} theme={t} />
          <PartList brand={brand} type="headlight" products={products} theme={t} />
          <PillButton to={`/brand/${meta.slug}`} variant={t.btn} className="mt-auto w-fit">All {brand} parts</PillButton>
        </div>
      </div>
    </article>
  );
}

function useIsDesktop() {
  const [d, setD] = useState(() => typeof window !== "undefined" && window.matchMedia("(min-width: 1024px)").matches);
  useLayoutEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const on = () => setD(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);
  return d;
}

/** Desktop: pinned section whose track pans horizontally with vertical scroll. Mobile / reduced motion: stacked panels. */
export default function MarqueGallery({ products }) {
  const reduce = useReducedMotion();
  const desktop = useIsDesktop();
  const wrap = useRef(null);
  const track = useRef(null);
  const [distance, setDistance] = useState(0);
  const { scrollYProgress } = useScroll({ target: wrap, offset: ["start start", "end end"] });
  const raw = useTransform(scrollYProgress, [0, 1], [0, -distance]);
  const x = useSpring(raw, { stiffness: 120, damping: 30, mass: 0.4 });
  const pan = desktop && !reduce;

  useLayoutEffect(() => {
    if (!pan || !track.current) return;
    const measure = () => setDistance(Math.max(0, track.current.scrollWidth - window.innerWidth));
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(track.current);
    window.addEventListener("resize", measure);
    return () => { ro.disconnect(); window.removeEventListener("resize", measure); };
  }, [pan, products.length]);

  const intro = (
    <div className="flex shrink-0 flex-col justify-end pb-4 lg:w-[30vw] lg:pb-10">
      <h2 className="font-display text-5xl font-extrabold leading-[0.95] md:text-7xl">Pick your<br />marque.</h2>
      <p className="mt-5 max-w-xs text-ink-2">Bumpers and headlights for every model we stock, grouped by brand.</p>
    </div>
  );

  if (!pan) {
    return (
      <section className="mx-auto max-w-7xl space-y-6 px-4 py-24 md:px-8" data-testid="bento-brands">
        {intro}
        {BRANDS.map((b) => <BrandPanel key={b} brand={b} products={products} />)}
      </section>
    );
  }

  return (
    <section ref={wrap} style={{ height: `calc(100vh + ${distance}px)` }} className="relative" data-testid="bento-brands">
      <div className="sticky top-0 flex h-[100dvh] flex-col justify-center overflow-hidden">
        <motion.div ref={track} style={{ x }} className="flex items-stretch gap-6 pl-[6vw] pr-[6vw] will-change-transform">
          {intro}
          {BRANDS.map((b) => <BrandPanel key={b} brand={b} products={products} className="h-[78vh] w-[78vw] max-w-[1200px] shrink-0" />)}
        </motion.div>
        <div className="mx-[6vw] mt-8 h-[2px] overflow-hidden rounded-full bg-ink/10" aria-hidden="true">
          <motion.div className="h-full w-full origin-left bg-signal" style={{ scaleX: scrollYProgress }} />
        </div>
      </div>
    </section>
  );
}
