import { Link, useNavigate } from "react-router-dom";
import { useCart } from "@/lib/cart";
import { Trash } from "@phosphor-icons/react";

export default function Cart() {
  const { items, setQty, remove, subtotal } = useCart();
  const nav = useNavigate();

  return (
    <div className="max-w-6xl mx-auto px-4 md:px-8 pt-32 pb-16 md:pt-40" data-testid="cart-page">
      <h1 className="font-display text-5xl md:text-6xl font-extrabold mb-10">Your cart.</h1>

      {items.length === 0 ? (
        <div className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-16 text-center" data-testid="empty-cart">
          <p className="text-ink-2 mb-6">Your cart is empty.</p>
          <Link to="/shop" className="inline-block rounded-full bg-ink text-white px-8 py-3 text-sm uppercase tracking-widest font-medium hover:bg-ink/90">Continue shopping</Link>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          <div className="md:col-span-2 space-y-4">
            {items.map((i) => (
              <div key={i.product_id} className="flex gap-4 rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-4" data-testid={`cart-item-${i.product_id}`}>
                <img src={i.image} alt={i.title} className="w-24 h-24 object-cover bg-canvas" />
                <div className="flex-1 flex flex-col">
                  <h3 className="font-display font-bold leading-snug">{i.title}</h3>
                  <div className="mt-auto flex items-center justify-between">
                    <div className="flex border border-ink/10">
                      <button onClick={() => setQty(i.product_id, i.qty - 1)} className="px-3 py-1.5 text-ink-2" data-testid={`cart-dec-${i.product_id}`}>−</button>
                      <span className="px-4 py-1.5 text-sm">{i.qty}</span>
                      <button onClick={() => setQty(i.product_id, i.qty + 1)} className="px-3 py-1.5 text-ink-2" data-testid={`cart-inc-${i.product_id}`}>+</button>
                    </div>
                    <span className="font-display font-bold text-signal">${(i.price * i.qty).toFixed(2)}</span>
                  </div>
                </div>
                <button onClick={() => remove(i.product_id)} className="text-ink-3 hover:text-red-600" data-testid={`cart-remove-${i.product_id}`}>
                  <Trash size={18} strokeWidth={1.5} />
                </button>
              </div>
            ))}
          </div>
          <aside className="rounded-[1.75rem] bg-white ring-1 ring-ink/[0.06] p-6 h-fit" data-testid="cart-summary">
            <h3 className="font-display text-xl font-bold mb-4">Summary</h3>
            <div className="flex justify-between text-sm mb-2"><span className="text-ink-2">Subtotal</span><span>${subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-sm mb-4"><span className="text-ink-2">Shipping</span><span className="text-signal">Free</span></div>
            <div className="border-t border-ink/10 pt-4 flex justify-between font-display text-xl font-bold"><span>Total</span><span>${subtotal.toFixed(2)}</span></div>
            <button onClick={() => nav("/checkout")} className="mt-6 w-full rounded-full bg-ink text-white py-4 text-sm uppercase tracking-widest font-medium hover:bg-ink/90" data-testid="proceed-checkout-btn">Proceed to checkout</button>
          </aside>
        </div>
      )}
    </div>
  );
}
