import { Link } from "react-router-dom";
import { ArrowUpRight } from "@phosphor-icons/react";
import { money } from "@/lib/catalog";
import { PART_LABEL_SINGULAR } from "@/lib/search";

export default function ProductCard({ p, className = "" }) {
  const part = PART_LABEL_SINGULAR[p.part_type] || p.part_type;
  return (
    <Link
      to={`/product/${p.slug}`}
      className={`group bezel block rounded-[1.75rem] transition-transform duration-700 ease-spring hover:-translate-y-1 ${className}`}
      data-testid={`product-card-${p.product_id}`}
    >
      <div className="bezel-core flex h-full flex-col overflow-hidden rounded-[calc(1.75rem-0.375rem)]">
        <div className="relative m-1.5 aspect-[4/3] overflow-hidden rounded-[1.15rem] bg-canvas">
          <img
            src={(p.images || [])[0]}
            alt={p.title}
            loading="lazy"
            className="h-full w-full object-cover transition-transform duration-1000 ease-expo group-hover:scale-[1.06]"
          />
        </div>
        <div className="flex flex-1 flex-col px-5 pb-5 pt-3">
          <div className="flex items-center justify-between gap-2 text-xs">
            <span className="text-ink-3">{p.position ? `${p.position} ` : ""}{part}</span>
            <span className={`rounded-full px-2.5 py-0.5 ${p.condition === "Refurbished" ? "bg-signal-soft text-signal" : "bg-canvas text-ink-2"}`}>{p.condition}</span>
          </div>
          <h3 className="mt-2.5 line-clamp-2 font-display text-lg font-bold leading-snug text-ink">{p.title}</h3>
          <p className="mt-1 font-mono text-[11px] text-ink-3">FITS {p.year_from}-{p.year_to}{p.chassis ? ` / ${p.chassis}` : ""}</p>
          <div className="mt-auto flex items-center justify-between pt-5">
            <span className="font-display text-2xl font-extrabold text-ink">{money(p.price)}</span>
            <span className="grid h-10 w-10 place-items-center rounded-full bg-canvas text-ink transition-[transform,background-color,color] duration-500 ease-spring group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:bg-ink group-hover:text-white">
              <ArrowUpRight size={16} />
            </span>
          </div>
        </div>
      </div>
    </Link>
  );
}

export function ProductCardSkeleton() {
  return (
    <div className="bezel rounded-[1.75rem]" aria-hidden="true">
      <div className="bezel-core animate-pulse rounded-[calc(1.75rem-0.375rem)] p-1.5">
        <div className="aspect-[4/3] rounded-[1.15rem] bg-canvas" />
        <div className="space-y-3 p-4">
          <div className="h-3 w-24 rounded-full bg-canvas" />
          <div className="h-4 w-full rounded-full bg-canvas" />
          <div className="h-4 w-2/3 rounded-full bg-canvas" />
          <div className="mt-4 h-6 w-20 rounded-full bg-canvas" />
        </div>
      </div>
    </div>
  );
}
