export const brandFromSlug = (slug) => BRANDS.find((b) => BRAND_META[b].slug === String(slug).toLowerCase());

let cache = null;
let inflight = null;

/** Loads the full active catalog once per session and shares it between components. */
export function useCatalog() {
  const [products, setProducts] = useState(cache);
  useEffect(() => {
    if (cache) return;
    inflight = inflight || api.get("/products?limit=1000").then(({ data }) => (cache = data));
    let alive = true;
    inflight.then((d) => alive && setProducts(d)).catch(() => alive && setProducts([]));
    return () => { alive = false; };
  }, []);
  return { products: products || [], loading: products === null };
}

/** { BMW: [{ model, chassis, year_from, year_to, label }], ... } built from the catalog. */
export function vehicleTree(products) {
  const tree = {};
  for (const p of products) {
    const key = `${p.model}|${p.chassis || ""}`;
    tree[p.brand] = tree[p.brand] || {};
    const v = (tree[p.brand][key] = tree[p.brand][key] || { model: p.model, chassis: p.chassis, year_from: p.year_from, year_to: p.year_to });
    v.year_from = Math.min(v.year_from, p.year_from);
    v.year_to = Math.max(v.year_to, p.year_to);
  }
  const out = {};
  for (const b of Object.keys(tree)) {
    out[b] = Object.values(tree[b])
      .map((v) => ({ ...v, label: v.chassis ? `${v.model} (${v.chassis})` : v.model }))
      .sort((a, z) => a.model.localeCompare(z.model, undefined, { numeric: true }) || z.year_from - a.year_from);
  }
  return out;
}

export const money = (n) => `$${Number(n).toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
